NAME = 'GerZurcher: Deutsche Zürcher Bibel von 1931.'
BOOK = 'Joshua'

CHAPTERS = {
    1: {
        1: 'NACH dem Tode Moses, des Knechtes des Herrn, sprach der Herr zu Josua, dem Sohne Nuns, dem Diener Moses: (a) 2Mo 33:11',
        2: 'Mein Knecht Mose ist gestorben; so mache dich nun auf, ziehe über den Jordan hier, du und dieses ganze Volk, in das Land, das ich ihnen, den Israeliten, gebe.',
        3: 'Jeden Ort, darauf eure Fußsohle treten wird, gebe ich euch, wie ich Mose versprochen habe. (a) 5Mo 11:24',
        4: 'Von der Wüste an und dem Libanon dort bis an den grossen Strom, den Euphratstrom, das ganze Land der Hethiter, und bis an das grosse Meer im Westen soll euer Gebiet reichen.',
        5: 'Niemand soll vor dir standhalten können dein ganzes Leben lang. Wie ich mit Mose gewesen bin, so will ich mit dir sein. Ich will dich nicht verlassen noch preisgeben. (1) V. 5-6: 5Mo 31:6 7',
        6: 'Sei fest und unentwegt; denn du sollst diesem Volke das Land zum Erbe austeilen, das ich ihm geben will, wie ich ihren Vätern geschworen habe.',
        7: 'Nur sei recht fest und unentwegt, genau zu tun nach allem, was dir mein Knecht Mose geboten hat. Weiche nicht davon, weder zur Rechten noch zur Linken, auf dass du Glück habest auf allen deinen Wegen. (a) 5Mo 5:32',
        8: 'Von diesem Gesetzbuch sollst du allzeit reden und darüber nachsinnen Tag und Nacht, dass du genau tust nach allem, was darin geschrieben steht; denn alsdann wird es dir auf deinen Wegen gelingen und wirst du Glück haben. (a) Ps 1:2',
        9: 'Habe ich dir nicht geboten: Sei fest und unentwegt? So lass dir nicht grauen und fürchte dich nicht; denn der Herr, dein Gott, ist mit dir auf allen deinen Wegen.',
        10: 'Da gebot Josua den Amtleuten des Volkes:',
        11: 'Geht durch das Lager und gebietet dem Volke: Macht euch Wegzehrung bereit; denn in drei Tagen sollt ihr hier über den Jordan gehen, dass ihr einziehet und das Land einnehmet, das euch der Herr, euer Gott, zu eigen gibt.',
        12: 'Und zu den Rubeniten, den Gaditen und dem halben Stamm Manasse sprach Josua:',
        13: 'Gedenket dessen, was euch Mose, der Knecht des Herrn, geboten hat: Der Herr, euer Gott, schafft euch Ruhe und gibt euch dieses Land. (a) 4Mo 32:20-22',
        14: 'Eure Frauen, eure Kinder und euer Vieh mögen in dem Lande bleiben, das euch Mose jenseits des Jordan gegeben hat; ihr aber, was streitbare Männer sind, sollt gerüstet vor euren Brüdern hinüberziehen und ihnen helfen,',
        15: 'bis der Herr euren Brüdern Ruhe schafft wie euch und auch sie das Land einnehmen, das ihnen der Herr, euer Gott, gibt. Alsdann mögt ihr in das Land eures Eigentums zurückkehren, das euch Mose, der Knecht des Herrn, jenseits des Jordan im Osten gegeben hat.',
        16: 'Und sie antworteten Josua: Alles, was du uns geboten hast, wollen wir tun; und wohin immer du uns sendest, dahin wollen wir gehen.',
        17: 'Ganz wie wir Mose gehorsam gewesen sind, so wollen wir auch dir gehorsam sein. Wenn nur der Herr, dein Gott, mit dir ist, wie er mit Mose war!',
        18: 'Ein jeder, der sich deinem Befehle widersetzt und deinen Worten nicht gehorcht in allem, was du ihm gebietest, der soll sterben; nur sei fest und unentwegt!',
    },
    2: {
        1: 'UND Josua, der Sohn Nuns, sandte von Sittim heimlich zwei Männer als Kundschafter und sprach: Geht hin, beseht euch das Land und Jericho. Da gingen sie hin und kamen in das Haus einer Dirne namens Rahab und legten sich daselbst schlafen.',
        2: 'Es ward aber dem König von Jericho gesagt: Siehe, heute nacht sind Männer von den Israeliten hier hereingekommen, das Land auszukundschaften.',
        3: 'Da sandte der König von Jericho zu Rahab und liess ihr sagen: Gib die Männer heraus, die zu dir ins Haus gekommen sind; denn sie sind gekommen, das ganze Land auszukundschaften.',
        4: 'Das Weib aber nahm die zwei Männer und versteckte sie; dann sprach sie: Gewiss, die Männer sind zu mir gekommen, aber ich wusste nicht, woher sie waren,',
        5: 'und als man eben das Tor schliessen wollte, da es finster wurde, gingen die Männer hinaus; ich weiss nicht, wohin sie gegangen sind. Jaget ihnen eilends nach, so werdet ihr sie einholen.',
        6: 'Sie hatte sie aber auf das Dach geführt und unter die Flachsstengel versteckt, die sie auf dem Dache hingestellt hatte.',
        7: 'Die Leute jedoch jagten ihnen nach auf dem Wege zum Jordan bis an die Furten, und man schloss das Tor, als die Verfolger draussen waren.',
        8: 'Jene aber hatten sich noch nicht schlafen gelegt, da stieg sie zu ihnen auf das Dach hinauf',
        9: 'und sprach zu ihnen: Ich weiss, dass euch der Herr das Land gegeben hat; denn ein Schrecken vor euch hat uns befallen, und alle Bewohner des Landes sind vor euch verzagt.',
        10: 'Denn wir haben gehört, wie der Herr das Wasser im Schilfmeer vor euch ausgetrocknet hat, als ihr aus Ägypten zoget, und was ihr den zwei Königen der Amoriter, Sihon und Og, jenseits des Jordan getan, an denen ihr den Bann vollstreckt habt. (a) 2Mo 14:21; 4Mo 21:24-35',
        11: 'Und als wir das hörten, verzagte unser Herz, und allen entsank der Mut vor euch; denn der Herr, euer Gott, ist Gott oben im Himmel und unten auf Erden. (a) 5Mo 4:39',
        12: 'Und nun schwöret mir doch bei dem Herrn, dass, wie ich euch Barmherzigkeit bewiesen habe, auch ihr an meines Vaters Hause Barmherzigkeit beweisen wollt, und gebt mir ein sicheres Zeichen, (a) Jos 6:23',
        13: 'dass ihr meinen Vater, meine Mutter, meine Brüder und meine Schwestern und all die Ihrigen am Leben lassen und uns vom Tode erretten wollt.',
        14: 'Da sprachen die Männer zu ihr: Mit unserm Leben bürgen wir für euch, sofern ihr unsere Sache da nicht verratet; und wenn der Herr uns das Land gibt, so wollen wir Barmherzigkeit und Treue an dir üben.',
        15: 'Da liess sie dieselben an einem Seil durch das Fenster hinab; denn ihr Haus war an die Stadtmauer angebaut, und sie wohnte an der Mauer.',
        16: 'Und sie sprach zu ihnen: Gehet ins Gebirge, dass die Verfolger euch nicht treffen, und verberget euch daselbst drei Tage lang, bis die Verfolger zurück sind; darnach mögt ihr eures Weges gehen.',
        17: 'Und die Männer sprachen zu ihr: Wir wollen dieses Eides ledig werden, den du uns hast schwören lassen:',
        18: 'Siehe, wenn wir in das Land kommen, sollst du diese Schnur von rotem Faden an das Fenster knüpfen, durch das du uns herabgelassen hast, und deinen Vater, deine Mutter, deine Brüder und deines Vaters ganzes Haus zu dir hineinnehmen.',
        19: 'Und wer dann zur Tür deines Hauses hinausgeht auf die Strasse, dessen Blut komme über sein Haupt, und wir sind frei von Schuld; wenn aber an irgend jemand, der bei dir im Hause ist, Hand gelegt wird, so komme sein Blut über unser Haupt.',
        20: 'Auch wenn du unsre Sache da verrätst, so sind wir des Eides ledig, den du uns hast schwören lassen.',
        21: 'Sie sprach: Es sei, wie ihr sagt! und entliess sie. Da gingen sie fort. Sie aber knüpfte die rote Schnur an das Fenster.',
        22: 'So gingen jene fort und kamen ins Gebirge und blieben drei Tage lang daselbst, bis die Verfolger zurück waren. Die Verfolger nämlich suchten auf dem ganzen Wege nach ihnen und fanden sie nicht.',
        23: 'Also stiegen die beiden Männer wieder vom Gebirge herab, gingen hinüber und kamen zu Josua, dem Sohne Nuns, und erzählten ihm alles, was ihnen begegnet war.',
        24: 'Und sie sprachen zu Josua: Der Herr hat das ganze Land in unsre Hand gegeben, und es sind auch alle Bewohner des Landes verzagt vor uns.',
    },
    3: {
        1: 'UND Josua machte sich frühe auf, und sie zogen weg von Sittim und kamen an den Jordan, er und ganz Israel, und blieben daselbst übernacht, ehe sie hinüberzogen.',
        2: 'Nach drei Tagen aber gingen die Amtleute durch das Lager',
        3: 'und geboten dem Volke: Sobald ihr seht, dass die levitischen Priester die Bundeslade des Herrn, eures Gottes, aufheben, so brechet auf von eurem Orte und folget ihr -',
        4: 'nur sei zwischen euch und ihr ein Abstand von etwa zweitausend Ellen; ihr dürft ihr nicht nahe kommen -, damit ihr wisset, welchen Weg ihr gehen sollt; denn ihr seid den Weg zuvor noch nie gegangen.',
        5: 'Und Josua sprach zum Volke: Weihet euch, denn morgen wird der Herr unter euch Wunder tun. (a) 2Mo 19:10-15',
        6: 'Und zu den Priestern sprach Josua: Hebt die Bundeslade auf und geht vor dem Volke her. Da hoben sie die Bundeslade auf und gingen vor dem Volke her.',
        7: 'Und der Herr sprach zu Josua: Heute will ich anfangen, dich gross zu machen vor ganz Israel, damit sie erkennen, dass ich mit dir sein werde, wie ich mit Mose gewesen bin. (a) Jos 4:14',
        8: 'Du aber gebiete den Priestern, welche die Bundeslade tragen: Wenn ihr an den Rand des Wassers des Jordan kommt, so bleibt im Jordan stehen.',
        9: 'Und Josua sprach zu Israel: Tretet heran und höret die Worte des Herrn, eures Gottes.',
        10: 'Dann sprach Josua: Daran sollt ihr erkennen, dass ein lebendiger Gott in eurer Mitte weilt und dass er die Kanaaniter, Hethiter, Hewiter, Pheresiter, Girgasiter, Amoriter und Jebusiter gewiss vor euch vertreiben wird:',
        11: 'Siehe, die Lade unsres Gottes, des Herrn der ganzen Erde, wird vor euch her durch den Jordan gehen.',
        12: 'So nehmt nun aus den Stämmen Israels zwölf Männer, aus jedem Stamme einen.',
        13: 'Wenn dann die Fußsohlen der Priester, welche die Lade unsres Gottes, des Herrn der ganzen Erde, tragen, in das Wasser des Jordan treten, so wird das Wasser des Jordan abreissen, und das Wasser, das von oben her zufliesst, wird stehen wie ein Damm.',
        14: 'Als nun das Volk aufbrach aus seinen Zelten, um über den Jordan zu gehen, indem die Priester, welche die Bundeslade trugen, vor dem Volke einher zogen,',
        15: 'und als die Träger der Lade an den Fluss kamen und die Füsse der Priester, welche die Lade trugen, in den Rand des Wassers tauchten - der Jordan aber tritt während der ganzen Erntezeit allenthalben über die Ufer -,',
        16: 'da blieb das Wasser, das von oben her kam, stehen; es erhob sich als ein Damm, sehr weit weg bei der Stadt Adam, die seitwärts von Zarthan liegt; das Wasser aber, das zum Meer der Steppe, dem Salzmeer, hinabfloss, verlief sich ganz. Also ging das Volk hindurch gegenüber Jericho.',
        17: 'Und die Priester, welche die Lade trugen, standen im Jordan still auf dem Trockenen, während ganz Israel trockenen Fusses hindurchging, bis alles Volk den Fluss völlig überschritten hatte.',
    },
    4: {
        1: 'Nachdem nun alles Volk den Jordan völlig überschritten hatte, sprach der Herr zu Josua:',
        2: 'Nehmt aus dem Volke zwölf Männer, aus jedem Stamme einen,',
        3: 'und gebietet ihnen: Hebt da aus dem Jordan, von der Stelle, wo die Füsse der Priester stillegestanden, zwölf Steine auf, nehmt sie mit euch hinüber und legt sie da nieder, wo ihr heute übernachten werdet.',
        4: 'Da rief Josua die zwölf Männer, die er aus Israel bestellt hatte, je einen aus jedem Stamme,',
        5: 'und Josua sprach zu ihnen: Geht vor der Lade des Herrn, eures Gottes, her mitten in den Jordan und hebet ein jeder einen Stein auf seine Achsel, nach der Zahl der Stämme Israels,',
        6: 'damit das ein Zeichen unter euch sei. Wenn dann künftig eure Kinder fragen: "Was bedeuten euch diese Steine?"',
        7: 'so sollt ihr zu ihnen sagen: "Dass das Wasser des Jordan vor der Bundeslade des Herrn abriss, als sie durch den Jordan zog. Das Wasser des Jordan riss ab; so sollen nun diese Steine Israel zum ewigen Gedächtnis dienen."',
        8: 'Da taten die Israeliten so, wie Josua geboten hatte: sie hoben zwölf Steine aus dem Jordan auf, wie der Herr zu Josua gesagt hatte, nach der Zahl der Stämme Israels, und nahmen sie mit sich hinüber nach dem Lagerplatz und legten sie dort nieder.',
        9: 'Zwölf Steine aber richtete Josua auf im Jordan, an der Stelle, wo die Füsse der Priester gestanden, welche die Bundeslade trugen; die sind dort geblieben bis auf diesen Tag.',
        10: 'Die Priester aber, welche die Lade trugen, standen im Jordan, bis alles ausgeführt war, was der Herr dem Josua geboten hatte dem Volke zu sagen, ganz wie Mose Josua befohlen hatte. Und das Volk ging eilends hinüber.',
        11: 'Als nun das ganze Volk völlig hinübergegangen war, zogen die Lade des Herrn und die Priester vor dem Volke her.',
        12: 'Und die Rubeniten und die Gaditen und der halbe Stamm Manasse gingen bewaffnet vor Israel hinüber, wie Mose zu ihnen geredet hatte. (a) 4Mo 32:29',
        13: 'Etwa 40 000 Mann stark zogen sie kriegsgerüstet vor dem Herrn her zum Streit, hinüber in die Steppe von Jericho.',
        14: 'An jenem Tage machte der Herr den Josua gross vor den Augen von ganz Israel, und sie fürchteten ihn, wie sie Mose gefürchtet hatten, sein ganzes Leben lang. (a) Jos 3:7',
        15: 'Und der Herr sprach zu Josua:',
        16: 'Gebiete den Priestern, welche die Lade des Gesetzes tragen, dass sie aus dem Jordan heraufsteigen.',
        17: 'Da gebot Josua den Priestern: Steiget herauf aus dem Jordan.',
        18: 'Als nun die Priester, welche die Bundeslade des Herrn trugen, aus dem Jordan heraufstiegen und ihre Fußsohlen kaum auf das Trockene gesetzt hatten, da kehrte das Wasser des Jordan an seinen Ort zurück und trat wie zuvor allenthalben über die Ufer.',
        19: 'Es war aber der zehnte Tag des ersten Monats, als das Volk aus dem Jordan heraufstieg, und sie lagerten sich in Gilgal, an der Ostgrenze von Jericho.',
        20: 'Jene zwölf Steine aber, die sie aus dem Jordan genommen hatten, richtete Josua in Gilgal auf,',
        21: 'und er sprach zu den Israeliten: Wenn in Zukunft eure Kinder ihre Väter fragen: "Was bedeuten diese Steine?"',
        22: 'so sollt ihr ihnen kundtun: "Trockenen Fusses ging Israel hier durch den Jordan."',
        23: 'Denn der Herr, euer Gott, liess das Wasser des Jordan vor euch vertrocknen, bis ihr drüben waret, wie der Herr, euer Gott, mit dem Schilfmeer getan hat, das er vor uns vertrocknen liess, bis wir drüben waren -, (a) 2Mo 14:21',
        24: 'damit alle Völker auf Erden erkennen, dass die Hand des Herrn stark ist, auf dass sie den Herrn, euren Gott, allezeit fürchten.',
    },
    5: {
        1: 'ALS nun alle Könige der Amoriter, die jenseits des Jordan gegen Westen wohnten, und alle Könige der Kanaaniter am Meere hörten, wie der Herr das Wasser des Jordan vor den Israeliten hatte vertrocknen lassen, bis sie drüben waren, da verzagte ihr Herz, und der Mut entsank ihnen vor den Israeliten.',
        2: 'Zu der Zeit sprach der Herr zu Josua: Mache dir steinerne Messer und beschneide die Israeliten wiederum, zum zweitenmal. (a) 2Mo 4:25',
        3: 'Da machte sich Josua steinerne Messer und beschnitt die Israeliten am Hügel Araloth.',
        4: 'Und das ist die Ursache, warum Josua sie beschnitt: alles Volk männlichen Geschlechts, das aus Ägypten gezogen war, alle Kriegsleute waren in der Wüste unterwegs gestorben bei ihrem Auszug aus Ägypten.',
        5: 'Denn alles Volk, das auszog, war beschnitten gewesen. Aber alles Volk, das in der Wüste unterwegs geboren war, bei ihrem Auszug aus Ägypten, war nicht beschnitten worden.',
        6: 'Denn vierzig Jahre war Israel in der Wüste gewandert, bis alles Volk umgekommen war - die Kriegsleute, die aus Ägypten gezogen -, weil sie der Stimme des Herrn nicht gehorcht hatten; denn der Herr hatte ihnen geschworen, dass er sie das Land nicht werde sehen lassen, das uns zu geben der Herr ihren Vätern geschworen hatte, ein Land, das von Milch und Honig fliesst, (a) 4Mo 14:22 23',
        7: 'und ihre Söhne hatte er an ihre Stelle treten lassen. Diese nun beschnitt Josua; denn sie waren unbeschnitten, weil man sie unterwegs nicht beschnitten hatte.',
        8: 'Und als das ganze Volk beschnitten war, blieben sie an Ort und Stelle im Lager, bis sie genesen waren.',
        9: 'Und der Herr sprach zu Josua: Heute habe ich die Schmach Ägyptens von euch abgewälzt. Daher nennt man jenen Ort Gilgal bis auf diesen Tag. (1) der Erzähler hörte aus dem Namen Gilgal (vermutlich: Steinkreis o. Steinhaufe) einen Anklang an das hebrW. für "wälzen" heraus.',
        10: 'Als nun die Israeliten in Gilgal lagerten, hielten sie das Passa am vierzehnten Tage des Monats am Abend in der Steppe von Jericho.',
        11: 'Und sie assen am Tage nach dem Passa vom Ertrag des Landes, ungesäuertes Brot und geröstetes Korn. An eben diesem Tage (a) 2Mo 12:39',
        12: 'hörte das Manna auf, als sie vom Ertrag des Landes assen, und die Israeliten bekamen kein Manna mehr, sondern in jenem Jahre assen sie von den Früchten des Landes Kanaan. (a) 2Mo 16:35',
        13: 'Als aber Josua bei Jericho war, erhob er einst seine Augen und sah, wie ein Mann ihm gegenüberstand, das blanke Schwert in der Hand. Und Josua ging auf ihn zu und sprach zu ihm: Gehörst du zu uns oder zu unsern Feinden? (a) 4Mo 22:23',
        14: 'Er sprach: Nein, sondern ich bin der Oberste über das Heer des Herrn; eben jetzt bin ich gekommen. Da fiel Josua auf sein Angesicht zur Erde, betete an und sprach zu ihm: Was hat mein Herr seinem Knechte zu sagen?',
        15: 'Und der Oberste über das Heer des Herrn sprach zu Josua: Ziehe deine Schuhe aus von deinen Füssen; denn die Stätte, da du stehst, ist heilig. Und Josua tat also. (a) 2Mo 3:5',
    },
    6: {
        1: 'JERICHO aber schloss und blieb verschlossen vor Israel. Niemand ging hinaus und niemand hinein.',
        2: 'Da sprach der Herr zu Josua: Siehe, ich gebe Jericho samt seinem Könige, all die tapfern Helden, in deine Hand.',
        3: 'So zieht denn um die Stadt, alle Kriegsleute, rings um die Stadt herum, einmal; so sollst du sechs Tage lang tun.',
        4: 'Und sieben Priester sollen sieben Posaunen aus Widderhörnern vor der Lade her tragen. Am siebenten Tage aber sollt ihr siebenmal um die Stadt herum ziehen, und die Priester sollen in die Posaunen stossen.',
        5: 'Und wenn man das Widderhorn bläst und ihr den Schall der Posaunen hört, so soll das ganze Volk ein lautes Feldgeschrei erheben; dann wird die Stadtmauer in sich zusammenstürzen, und das Volk soll hinaufsteigen, ein jeder gerade vor sich hin.',
        6: 'Da rief Josua, der Sohn Nuns, die Priester und sprach zu ihnen: Hebt die Bundeslade auf, und sieben Priester sollen sieben Posaunen aus Widderhörnern vor der Lade des Herrn her tragen.',
        7: 'Zum Volke aber sprach er: Geht und zieht um die Stadt herum; die Gerüsteten aber sollen vor der Lade des Herrn her gehen.',
        8: 'Als Josua dem Volke dies befahl, setzten sich die sieben Priester, welche die sieben Posaunen aus Widderhörnern vor dem Herrn her trugen, in Bewegung und stiessen in die Posaunen; die Bundeslade des Herrn aber folgte ihnen.',
        9: 'Und die Gerüsteten gingen vor den Priestern her, die in die Posaunen stiessen, und die Nachhut folgte der Lade, während man in einem fort in die Posaunen stiess.',
        10: 'Dem Volke aber hatte Josua geboten: Ihr sollt kein Feldgeschrei erheben, noch eure Stimme hören lassen; auch soll kein Wort aus eurem Munde kommen bis auf den Tag, wo ich zu euch sagen werde: "Erhebet das Feldgeschrei!" dann sollt ihr das Feldgeschrei erheben.',
        11: 'So liess er die Lade des Herrn einmal rings um die Stadt herum ziehen. Dann kamen sie wieder in das Lager und blieben darin übernacht.',
        12: 'Und am andern Morgen stand Josua frühe auf, und die Priester trugen die Lade des Herrn,',
        13: 'während die sieben Priester die sieben Posaunen aus Widderhörnern vor der Lade des Herrn her trugen und in einem fort in die Posaunen stiessen und während die Gerüsteten vor ihnen her gingen, die Nachhut aber der Lade des Herrn folgte, wobei man in einem fort in die Posaunen stiess.',
        14: 'So zogen sie am zweiten Tage einmal um die Stadt; dann kamen sie wieder in das Lager. Das taten sie sechs Tage lang.',
        15: 'Am siebenten Tage aber machten sie sich frühe auf, als die Morgenröte heraufkam, und zogen in derselben Weise siebenmal um die Stadt; nur an diesem Tage zogen sie siebenmal um die Stadt.',
        16: 'Beim siebenten Mal aber stiessen die Priester in die Posaunen; da sprach Josua zum Volke: Erhebet das Feldgeschrei; denn der Herr gibt euch die Stadt.',
        17: 'Und die Stadt soll mit allem, was darin ist, dem Bann des Herrn verfallen sein; nur die Dirne Rahab soll am Leben bleiben, sie und alle, die bei ihr im Hause sind, weil sie die Boten versteckt hat, die wir aussandten. (a) 5Mo 20:16 17; Jos 2',
        18: 'Nur hütet euch vor dem Gebannten, dass euch nicht gelüste, etwas davon zu nehmen und so das Lager Israels durch euch dem Bann verfalle und ins Unglück komme. (a) 5Mo 13:17',
        19: 'Alles Silber und Gold und die ehernen und eisernen Geräte sind dem Herrn geweiht; in den Schatz des Herrn soll es kommen.',
        20: 'Da erhob das Volk das Feldgeschrei, und sie stiessen in die Posaunen. Als nun das Volk den Schall der Posaunen hörte und laut das Feldgeschrei erhob, stürzte die Mauer in sich zusammen, und das Volk erstieg die Stadt, ein jeder gerade vor sich hin. So nahmen sie die Stadt ein.',
        21: 'Und sie vollstreckten den Bann an allem, was in der Stadt war, mit der Schärfe des Schwertes, an Mann und Weib, an jung und alt, an Rind, Schaf und Esel.',
        22: 'Zu den beiden Männern aber, die das Land ausgekundschaftet hatten, sprach Josua: Gehet in das Haus der Dirne und führet das Weib mit allen ihren Angehörigen von dort heraus, wie ihr es ihr geschworen habt.',
        23: 'Da gingen die Jünglinge, die Kundschafter, hinein und führten Rahab, ihren Vater und ihre Mutter, ihre Brüder und alle ihre Angehörigen hinaus; auch alle ihre Verwandten führten sie hinaus und brachten sie draussen vor dem Lager Israels unter.',
        24: 'Die Stadt aber verbrannten sie und alles, was darin war; nur das Silber und Gold und die ehernen und eisernen Geräte taten sie in den Schatz im Hause des Herrn.',
        25: 'So liess Josua die Dirne Rahab samt ihrer Familie und allen Angehörigen am Leben; und sie blieb in Israel wohnen bis auf diesen Tag, weil sie die Boten versteckt hatte, die Josua ausgesandt, um Jericho auszukundschaften. (a) Jos 2:12 13',
        26: 'Damals liess Josua die Leute schwören: Verflucht vor dem Herrn ist der Mann, der sich aufmacht und diese Stadt wieder baut; wenn er ihren Grund legt, koste es ihn seinen erstgebornen, und wenn er ihre Tore setzt, seinen jüngsten Sohn. (1) d.h. Jericho. (a) 1Kön 16:34',
        27: 'So war der Herr mit Josua, und sein Ruf ging durch das ganze Land.',
    },
    7: {
        1: 'ABER Israel vergriff sich an dem Gebannten; denn Achan, der Sohn Charmis, des Sohnes Sabdis, des Sohnes Serahs vom Stamme Juda, nahm etwas von dem Gebannten. Da entbrannte der Zorn des Herrn wider Israel. (a) Jos 6:18; 22:20',
        2: 'Und Josua sandte Männer aus von Jericho nach Ai, das bei Beth-Awen östlich von Bethel liegt, und sprach zu ihnen: Gehet hinauf und kundschaftet das Land aus. Und die Männer gingen hinauf und kundschafteten Ai aus.',
        3: 'Und da sie wieder zu Josua kamen, sprachen sie zu ihm: Es muss nicht das ganze Volk hinaufziehen; nur etwa zwei- oder dreitausend Mann mögen hinaufziehen und Ai schlagen. Bemühe nicht das ganze Volk dorthin; denn ihrer sind wenige.',
        4: 'Also zogen vom Volke etwa dreitausend Mann hinauf. Aber sie flohen vor den Männern von Ai,',
        5: 'und die Männer von Ai erschlugen etwa 36 Mann von ihnen und verfolgten sie vor dem Tor bis zu den Steinbrüchen und schlugen sie am Abhange. Da zerfloss das Herz des Volkes und ward zu Wasser.',
        6: 'Josua aber zerriss seine Kleider und fiel auf sein Angesicht zur Erde vor der Lade des Herrn bis zum Abend, er und die Ältesten Israels, und sie streuten Staub auf ihr Haupt.',
        7: 'Und Josua sprach: Ach Herr, warum doch hast du dieses Volk über den Jordan geführt, um uns in die Hand der Amoriter zu geben, dass sie uns vernichten? O wären wir doch jenseits des Jordan geblieben!',
        8: 'Ich bitte dich, Herr, was soll ich sagen, nachdem Israel seinen Feinden den Rücken gekehrt hat?',
        9: 'Wenn das die Kanaaniter und alle Bewohner des Landes hören, so werden sie uns umzingeln und unsern Namen von der Erde ausrotten. Was willst du dann für deinen grossen Namen tun?',
        10: 'Da sprach der Herr zu Josua: Stehe auf! Warum denn liegst du auf deinem Angesicht?',
        11: 'Israel hat sich versündigt; ja, sie haben die Verpflichtung übertreten, die ich ihnen auferlegt habe, und haben sogar von dem Gebannten genommen, davon gestohlen, es verheimlicht und unter ihr Gerät getan.',
        12: 'Darum kann Israel vor seinen Feinden nicht bestehen, sondern muss seinen Feinden den Rücken kehren; denn es ist dem Banne verfallen. Ich werde künftig nicht mit euch sein, wenn ihr nicht das Gebannte aus eurer Mitte vertilgt.',
        13: 'Stehe auf, weihe das Volk und sprich: "Weihet euch auf morgen, denn also spricht der Herr, der Gott Israels: Es ist Gebanntes in deiner Mitte, Israel; du kannst vor deinen Feinden nicht bestehen, bis ihr das Gebannte aus eurer Mitte wegschafft." (a) 2Mo 19:10',
        14: 'Darum sollt ihr morgen früh herzutreten, Stamm für Stamm; und der Stamm, den der Herr durchs Los bezeichnen wird, soll herzutreten, Geschlecht für Geschlecht; und das Geschlecht, das der Herr bezeichnen wird, soll herzutreten, Haus für Haus; und das Haus, das der Herr bezeichnen wird, soll herzutreten, Mann für Mann.',
        15: 'Und wer im Besitze des Gebannten betroffen wird, den soll man verbrennen samt allem, was er hat, weil er die Verordnung des Herrn übertreten und eine Schandtat in Israel begangen hat.',
        16: 'Da liess Josua am andern Morgen früh Israel herzutreten, Stamm für Stamm; und das Los traf den Stamm Juda.',
        17: 'Dann liess er die Geschlechter Judas herzutreten, und es traf das Geschlecht der Serahiter. Dann liess er das Geschlecht der Serahiter herzutreten, Haus für Haus, und es traf (das Haus) Sabdis.',
        18: 'Dann liess er dessen Haus herzutreten, Mann für Mann, und es traf Achan, den Sohn Charmis, des Sohnes Sabdis, des Sohnes Serahs aus dem Stamme Juda.',
        19: 'Und Josua sprach zu Achan: Mein Sohn, gib doch dem Herrn, dem Gott Israels, die Ehre und bekenne ihm und sage mir, was du getan hast. Verbirg nichts vor mir.',
        20: "Da antwortete Achan dem Josua und sprach: In der Tat, ich bin's gewesen, der sich an dem Herrn, dem Gott Israels, versündigt hat; das und das habe ich getan.",
        21: 'Ich sah unter der Beute einen schönen babylonischen Mantel und zweihundert Lot Silber und eine goldene Zunge, fünfzig Lot schwer; danach gelüstete mich, und ich nahm es. Siehe, der Mantel ist innerhalb meines Zeltes in der Erde vergraben und das Geld darunter.',
        22: 'Da sandte Josua Boten hin, die eilten in das Zelt; und siehe, er war in seinem Zelte vergraben und das Geld darunter.',
        23: 'Und sie nahmen die Sachen aus dem Zelte weg und brachten sie zu Josua und zu ganz Israel und schütteten sie vor dem Herrn aus.',
        24: 'Da nahm Josua, und ganz Israel mit ihm, Achan, den Sohn Serahs, und das Silber, den Mantel und die goldene Zunge, und seine Söhne und Töchter, auch seine Rinder, Esel und Schafe, sein Zelt und alles, was er hatte, und man führte sie hinauf in das Tal Achor.',
        25: 'Und Josua sprach: Wie hast du uns ins Unglück gebracht! So bringe dich denn der Herr ins Unglück an diesem Tage! Und ganz Israel steinigte ihn.',
        26: 'Dann errichtete man über ihm einen grossen Steinhaufen, (der dort liegt) bis auf diesen Tag. Der Herr aber liess ab von der Glut seines Zornes. Daher heisst jene Stätte Tal Achor bis auf diesen Tag. (1) der Erzähler hörte aus dem Namen Achor einen Anklang an das hebrW. für "ins Unglück bringen" heraus. - V. 25',
    },
    8: {
        1: 'UND der Herr sprach zu Josua: Fürchte dich nicht und sei unverzagt! Nimm alles Kriegsvolk mit dir und mache dich auf und ziehe hinauf nach Ai. Siehe, ich gebe den König von Ai samt seinem Volke, seiner Stadt und seinem Lande in deine Hand.',
        2: 'Und du sollst mit Ai und seinem Könige tun, wie du mit Jericho und seinem Könige getan hast, nur dass ihr ihre Beute und ihr Vieh unter euch teilen dürft. Lege der Stadt auf der Westseite einen Hinterhalt. (a) Jos 6:21; 5Mo 2:34 35; 3:6',
        3: 'Da machte sich Josua auf und alles Kriegsvolk, hinauf nach Ai zu ziehen. Und Josua erwählte die 30 000 streitbarsten Männer und sandte sie aus bei Nacht',
        4: 'und gebot ihnen: Sehet zu! ihr sollt euch im Westen gegen die Stadt in den Hinterhalt legen, aber nicht gar zu weit von der Stadt, und seid alle bereit.',
        5: 'Ich aber und alles Volk, das bei mir ist, wir wollen gegen die Stadt vorgehen. Und wenn sie dann ausrücken, uns entgegen, wie das erstemal, so wollen wir vor ihnen fliehen.',
        6: 'Und sie werden uns nachrücken, bis wir sie von der Stadt weggelockt haben; denn sie werden sagen: "Sie fliehen vor uns wie das erstemal." Und wenn wir vor ihnen fliehen,',
        7: 'so sollt ihr euch aus dem Hinterhalte aufmachen und die Stadt einnehmen, und der Herr, euer Gott, wird sie in eure Hand geben.',
        8: 'Wenn ihr aber die Stadt eingenommen habt, so steckt sie in Brand; tut nach dem Worte des Herrn. Seht, ich gebiete es euch.',
        9: 'Also sandte sie Josua aus, und sie gingen in den Hinterhalt und lagerten sich zwischen Bethel und Ai, westlich von Ai. Josua aber blieb jene Nacht unter dem Volke.',
        10: 'Am andern Morgen aber in der Frühe musterte Josua das Volk und zog hinauf mit den Ältesten Israels vor dem Volke her nach Ai.',
        11: 'Und alles Kriegsvolk, das bei ihm war, zog hinauf, und sie rückten heran und kamen vor die Stadt und lagerten sich nördlich von Ai, sodass das Tal zwischen ihnen und Ai lag.',
        12: 'Dann nahm er etwa fünftausend Mann und legte sie in den Hinterhalt zwischen Bethel und Ai, westlich von der Stadt.',
        13: 'Und sie stellten das Volk auf, das ganze Lager, das im Norden der Stadt war, und die Nachhut im Westen der Stadt. Josua aber ging in jener Nacht mitten in das Tal.',
        14: 'Als aber der König von Ai das sah, rückten die Männer der Stadt in der Frühe eilends aus, wider Israel zu streiten, der König und sein ganzes Volk, an den Abhang vor der Araba; er wusste aber nicht, dass ihm im Westen der Stadt ein Hinterhalt gelegt war.',
        15: 'Josua aber und ganz Israel liessen sich von ihnen schlagen und flohen auf dem Wege zur Wüste.',
        16: 'Da wurde alles Volk, das in der Stadt war, aufgeboten, dass es ihnen nachjage, und sie jagten Josua nach und liessen sich so von der Stadt weglocken.',
        17: 'Und es blieb nicht ein Mann in Ai, der nicht ausgezogen wäre, Israel nachzujagen; und sie liessen die Stadt offenstehen und jagten Israel nach.',
        18: 'Da sprach der Herr zu Josua: Recke die Lanze, die du in der Hand hast, aus gegen Ai; denn in deine Hand will ich es geben. Und Josua reckte die Lanze, die er in der Hand hatte, gegen die Stadt aus.',
        19: 'Der Hinterhalt aber brach eilends auf aus seiner Stellung, und sie drangen, da er seine Hand ausreckte, rasch in die Stadt ein, nahmen sie und steckten sie alsbald in Brand.',
        20: 'Als nun die Männer von Ai sich umwandten, da sahen sie, wie der Rauch der Stadt zum Himmel aufstieg, und sie hatten nicht Kraft, zu fliehen, weder hierhin noch dorthin. Das Volk aber, das zur Wüste floh, kehrte sich um gegen die Verfolger.',
        21: 'Denn als Josua und ganz Israel sahen, dass der Hinterhalt die Stadt eingenommen hatte und dass der Rauch der Stadt aufstieg, machten sie kehrt und schlugen die Männer von Ai.',
        22: 'Und die andern rückten aus der Stadt ihnen entgegen, sodass die von Ai mitten zwischen die Israeliten gerieten; diese kamen von beiden Seiten und schlugen sie, bis niemand unter ihnen übrigblieb, der entflohen und entronnen wäre.',
        23: 'Den König von Ai aber nahmen sie lebendig gefangen und brachten ihn zu Josua.',
        24: 'Und als die Israeliten alle Bewohner von Ai auf freiem Felde, am Abhang, wo sie ihnen nachgejagt, niedergemacht hatten und alle bis auf den letzten Mann durch die Schärfe des Schwertes gefallen waren, kehrte ganz Israel zurück nach Ai und schlug es mit der Schärfe des Schwertes.',
        25: 'Und derer, die an jenem Tage fielen, Männer und Frauen, waren im ganzen zwölftausend, alle Leute von Ai.',
        26: 'Josua aber zog seine Hand, die er mit der Lanze ausgereckt hielt, nicht zurück, bis er an allen Bewohnern von Ai den Bann vollstreckt hatte.',
        27: 'Nur das Vieh und die Beute dieser Stadt nahm Israel für sich nach dem Worte des Herrn, das er Josua geboten hatte.',
        28: 'Und Josua äscherte Ai ein und machte es zu einem Trümmerhaufen für ewige Zeiten, zu einer Wüstenei, die noch heute da ist.',
        29: 'Den König von Ai aber liess er an den Pfahl hängen bis zum Abend. Als aber die Sonne unterging, gebot Josua, dass man seinen Leichnam von dem Pfahle herabnehme; und sie warfen ihn vor das Tor der Stadt und errichteten über ihm einen grossen Steinhaufen, (der dort liegt) bis auf diesen Tag. (a) 5Mo 21:23',
        30: 'DAMALS baute Josua dem Herrn, dem Gott Israels, einen Altar auf dem Berge Ebal,',
        31: 'wie Mose, der Knecht des Herrn, Israel geboten hatte, wie es geschrieben steht im Buche des Gesetzes Moses, einen Altar von unbehauenen Steinen, über die man kein Eisen geschwungen hatte, und sie brachten dem Herrn darauf Brandopfer dar und schlachteten Heilsopfer. (a) 2Mo 20:25; 5Mo 27:5 6',
        32: 'Und er schrieb daselbst vor den Augen Israels auf die Steine eine Abschrift des Gesetzes Moses, das dieser aufgezeichnet hatte.',
        33: 'Und ganz Israel samt seinen Ältesten, Amtleuten und Richtern stand zu beiden Seiten der Lade, den levitischen Priestern gegenüber, welche die Bundeslade des Herrn trugen, die Fremdlinge sowohl als die Einheimischen, die eine Hälfte gegen den Berg Garizim, die andre gegen den Berg Ebal hin, wie Mose, der Knecht des Herrn, vormals geboten hatte, das Volk Israel zu segnen. (a) 5Mo 27:12',
        34: 'Darnach las er alle Worte des Gesetzes vor, den Segen und den Fluch, ganz wie es im Gesetzbuche geschrieben steht.',
        35: 'Von allem, was Mose geboten hatte, war nicht ein Wort, das Josua der ganzen Gemeinde Israels nicht vorgelesen hätte, auch den Frauen und Kindern und den Fremdlingen, die mit ihnen zogen.',
    },
    9: {
        1: 'ALS das nun alle Könige hörten, die jenseits des Jordan, auf dem Gebirge und in der Niederung und am ganzen Gestade des grossen Meeres bis an den Libanon hin wohnten, die Hethiter, Amoriter, Kanaaniter, Pheresiter, Hewiter und Jebusiter,',
        2: 'da taten sie sich einmütig zusammen, wider Josua und wider Israel zu streiten.',
        3: 'Als aber die Bewohner von Gibeon hörten, was Josua mit Jericho und Ai getan hatte,',
        4: 'da handelten sie ihrerseits mit List: sie gingen hin und versahen sich mit Wegzehrung und nahmen alte Säcke auf ihre Esel und alte, zerrissene und geflickte Weinschläuche,',
        5: 'taten alte und geflickte Schuhe an ihre Füsse und zogen alte Kleider an; und alles Brot ihrer Wegzehrung war hart und zerbröckelt.',
        6: 'Dann gingen sie zu Josua ins Lager nach Gilgal und sprachen zu ihm und zu den Männern Israels: Aus fernem Lande kommen wir; so schliesst nun einen Bund mit uns.',
        7: 'Da sprachen die Männer Israels zu den Hewitern: Vielleicht wohnt ihr mitten unter uns; wie können wir da einen Bund mit euch schliessen? (a) Jos 11:19',
        8: 'Sie aber sprachen zu Josua: Wir sind deine Knechte. Josua fragte sie: Wer seid ihr und woher kommt ihr?',
        9: 'Sie antworteten ihm: Aus sehr fernem Lande kommen deine Knechte um des Namens des Herrn, deines Gottes, willen, denn wir haben von ihm gehört und was er alles in Ägypten getan',
        10: 'und was er alles den beiden Königen der Amoriter jenseits des Jordan getan, Sihon, dem Könige von Hesbon, und Og, dem Könige von Basan, der zu Astharoth wohnte. (a) 4Mo 21:24-35',
        11: 'Darum sprachen unsre Ältesten und alle Bewohner unsres Landes zu uns: Nehmt Zehrung mit euch auf den Weg und geht ihnen entgegen und sprecht zu ihnen: Wir sind eure Knechte; so schliesst nun einen Bund mit uns.',
        12: 'Unser Brot da haben wir noch warm aus unsern Häusern mit auf den Weg genommen, als wir auszogen, um zu euch zu gehen; und nun, seht, ist es hart geworden und zerbröckelt.',
        13: 'Und die Weinschläuche da, die neu waren, als wir sie füllten, seht, die sind zerrissen; und unsre Kleider da und unsre Schuhe, die sind ganz abgenutzt vom weiten Weg.',
        14: 'Da nahmen die Männer von ihrer Wegzehrung, den Herrn aber befragten sie nicht.',
        15: 'Und Josua gewährte ihnen Freundschaft und schloss einen Bund mit ihnen, sie am Leben zu lassen; und die Obersten der Gemeinde schwuren ihnen.',
        16: 'Aber drei Tage nachdem sie den Bund mit ihnen geschlossen hatten, hörten sie, dass jene aus ihrer Nähe waren und unter ihnen wohnten.',
        17: 'Da brach Israel auf und kam am dritten Tage zu ihren Städten; es waren dies Gibeon, Kephira, Beeroth und Kirjath-Jearim.',
        18: 'Und Israel schlug sie nicht, weil ihnen die Obersten der Gemeinde bei dem Herrn, dem Gott Israels, geschworen hatten; aber die ganze Gemeinde murrte wider die Obersten.',
        19: 'Da sprachen alle Obersten zu der ganzen Gemeinde: Wir haben ihnen bei dem Herrn, dem Gott Israels, geschworen; darum dürfen wir sie nicht antasten.',
        20: 'Aber das wollen wir ihnen tun, da wir sie doch am Leben lassen müssen, damit nicht ein Zorn über uns komme um des Eides willen, den wir ihnen geschworen haben:',
        21: 'sie sollen am Leben bleiben, aber Holzhauer und Wasserschöpfer für die ganze Gemeinde werden. Da tat die ganze Gemeinde, wie ihnen die Obersten gesagt hatten.',
        22: 'Und Josua rief sie und redete mit ihnen also: Warum habt ihr uns betrogen und gesagt: "Wir sind sehr weit von euch weg", da ihr doch unter uns wohnt?',
        23: 'Und nun, verflucht seid ihr, und nie sollt ihr aufhören, Knechte zu sein und Holzhauer und Wasserschöpfer für das Haus meines Gottes.',
        24: 'Sie antworteten Josua: Es ist halt deinen Knechten kundgeworden, dass der Herr, dein Gott, seinem Knechte Mose geboten hat, euch das ganze Land zu geben und alle Bewohner des Landes vor euch zu vertilgen: da fürchteten wir von eurer Seite grosse Gefahr für unser Leben und haben das getan.',
        25: 'Nun aber sind wir ja in deiner Hand; was dich gut und recht dünkt, uns zu tun, das tue.',
        26: 'Und er tat ihnen so und errettete sie aus der Hand der Israeliten, dass sie sie nicht töteten.',
        27: 'Und Josua machte sie an jenem Tage zu Holzhauern und Wasserschöpfern für die Gemeinde und für den Altar des Herrn an dem Orte, den er erwählen würde, (und so ist es geblieben) bis auf diesen Tag.',
    },
    10: {
        1: 'ALS aber Adoni-Zedek, der König von Jerusalem, hörte, dass Josua Ai eingenommen und an ihm den Bann vollstreckt hatte - wie Jericho und seinem Könige, so hatte er auch Ai und seinem Könige getan - und dass die Bewohner von Gibeon mit Israel Frieden gemacht hatten und in seiner Mitte blieben,',
        2: 'da fürchtete er sich sehr; denn Gibeon war eine grosse Stadt, wie eine der Königsstädte, und sie war noch grösser als Ai, und alle ihre Männer waren streitbar.',
        3: 'Darum sandte Adoni-Zedek, der König von Jerusalem, zu Hoham, dem Könige von Hebron, und zu Piream, dem Könige von Jarmuth, und zu Japhia, dem Könige von Lachis, und zu Debir, dem Könige von Eglon, und liess ihnen sagen:',
        4: 'Kommt herauf zu mir und helft mir, dass wir Gibeon schlagen; denn es hat mit Josua und den Israeliten Frieden gemacht.',
        5: 'Da kamen zusammen und zogen hinauf die fünf Könige der Amoriter, der König von Jerusalem, der König von Hebron, der König von Jarmuth, der König von Lachis und der König von Eglon, mit ihrem ganzen Heere und belagerten Gibeon und stritten wider die Stadt.',
        6: 'Aber die Männer von Gibeon sandten zu Josua ins Lager nach Gilgal und liessen ihm sagen: Ziehe deine Hand nicht ab von deinen Knechten, komm eilends herauf zu uns und errette uns und hilf uns; denn alle Könige der Amoriter, die auf dem Gebirge wohnen, haben sich wider uns zusammengetan.',
        7: 'Und Josua zog hinauf von Gilgal, er und alles Kriegsvolk mit ihm und alle streitbaren Männer.',
        8: 'Und der Herr sprach zu Josua: Fürchte dich nicht vor ihnen; denn ich gebe sie in deine Hand. Niemand unter ihnen wird vor dir standhalten können.',
        9: 'Und Josua kam plötzlich über sie; die ganze Nacht durch war er von Gilgal hinaufgezogen.',
        10: 'Und der Herr verwirrte sie vor Israel, und sie brachten ihnen zu Gibeon eine schwere Niederlage bei, jagten ihnen nach auf dem Wege zum Steig von Beth-Horon und schlugen sie bis Aseka und bis Makkeda.',
        11: 'Und als sie auf ihrer Flucht vor Israel am Abhange von Beth-Horon waren, liess der Herr grosse Steine vom Himmel auf sie fallen bis nach Aseka, sodass sie starben; derer, die von den Hagelsteinen starben, waren mehr als derer, die Israel mit dem Schwerte erschlug.',
        12: 'Damals, an dem Tage, als der Herr die Amoriter den Israeliten preisgab, redete Josua mit dem Herrn und sprach in Gegenwart Israels: Sonne, stehe still zu Gibeon, / und Mond im Tal von Ajalon! /',
        13: 'Da stand die Sonne still, und der Mond blieb stehen, / bis das Volk Rache genommen an seinen Feinden. Steht das nicht im Buche des Wackern? So stand die Sonne still mitten am Himmel und eilte nicht, unterzugehen, beinahe einen ganzen Tag. (a) 2Sa 1:18',
        14: 'Und niemals, nicht vorher und nicht nachher, hat der Herr auf eines Mannes Stimme gehört, wie an diesem Tage; denn der Herr stritt für Israel.',
        15: 'Dann zog Josua ins Lager nach Gilgal zurück und ganz Israel mit ihm.',
        16: 'Jene fünf Könige aber flohen und versteckten sich in der Höhle bei Makkeda.',
        17: 'Da wurde Josua gemeldet: Man hat die fünf Könige gefunden, und zwar versteckt in der Höhle bei Makkeda.',
        18: 'Josua sprach: So wälzet grosse Steine vor den Eingang der Höhle und stellet Männer davor, sie zu bewachen.',
        19: 'Ihr aber, bleibt nicht stehen, sondern jaget euren Feinden nach und schlaget ihre Nachhut und lasst sie nicht in ihre Städte kommen; denn der Herr, euer Gott, gibt sie in eure Hand.',
        20: 'Als nun Josua und die Israeliten ihnen eine sehr schwere Niederlage beigebracht hatten, bis ihr letzter Mann gefallen war - was aber von ihnen hatte entrinnen können, war in die festen Städte entkommen -,',
        21: 'da kehrte das ganze Volk wohlbehalten ins Lager zu Josua nach Makkeda zurück; niemand wagte mehr, gegen Israel zu mucksen.',
        22: 'Josua aber sprach: Öffnet den Eingang der Höhle und bringt jene fünf Könige aus der Höhle heraus zu mir.',
        23: 'Sie taten also und brachten die fünf Könige aus der Höhle heraus zu ihm: den König von Jerusalem, den König von Hebron, den König von Jarmuth, den König von Lachis und den König von Eglon.',
        24: 'Als man aber jene Könige zu Josua herausbrachte, berief er alle Männer Israels und sprach zu den Obersten des Kriegsvolkes, die mit ihm gezogen waren: Tretet herzu und setzt diesen Königen den Fuss auf den Nacken! Da traten sie herzu und setzten ihnen den Fuss auf den Nacken.',
        25: 'Dann sprach Josua zu ihnen: Fürchtet euch nicht und seid unverzagt, seid fest und unentwegt; denn so wird der Herr allen euren Feinden tun, wider die ihr streitet.',
        26: 'Darnach liess Josua sie totschlagen und an fünf Pfähle hängen. Und sie hingen an den Pfählen bis zum Abend.',
        27: 'Als aber die Sonne unterging, gebot Josua, dass man sie von den Pfählen nehme und in die Höhle werfe, darin sie sich verborgen hatten. Dann legte man grosse Steine vor den Eingang der Höhle; die sind noch dort bis auf den heutigen Tag. (a) 5Mo 21:23',
        28: 'Auch Makkeda nahm Josua an demselben Tage ein und schlug es samt seinem Könige mit der Schärfe des Schwertes, indem er an der Stadt und allem Lebenden, das darin war, den Bann vollstreckte, ohne jemand übrigzulassen; und er tat dem Könige von Makkeda, wie er dem Könige von Jericho getan hatte.',
        29: 'Darnach zog Josua und ganz Israel mit ihm von Makkeda nach Libna, und sie stritten wider Libna.',
        30: 'Und der Herr gab auch diese Stadt samt ihrem König in die Hand Israels, und sie schlugen alles Lebende, das darin war, mit der Schärfe des Schwertes, ohne jemand übrigzulassen; und sie taten ihrem Könige, wie sie dem Könige von Jericho getan hatten.',
        31: 'Darnach zog Josua und ganz Israel mit ihm von Libna nach Lachis, und sie belagerten und bekriegten es.',
        32: 'Und der Herr gab Lachis in die Hand Israels, und sie nahmen es am zweiten Tage ein und schlugen es samt allem Lebenden, das darin war, mit der Schärfe des Schwertes, ganz wie sie Libna getan hatten.',
        33: 'Damals zog Horam, der König von Geser, herauf, Lachis zu helfen; aber Josua schlug ihn samt seinem Volke, dass nicht einer übrigblieb.',
        34: 'Darnach zog Josua und ganz Israel mit ihm von Lachis nach Eglon, und sie belagerten und bekriegten es.',
        35: 'Und sie nahmen es am selben Tage ein und schlugen es mit der Schärfe des Schwertes; an allem Lebenden aber, das darin war, vollstreckten sie an jenem Tage den Bann, ganz wie sie Lachis getan hatten.',
        36: 'Darnach zog Josua und ganz Israel mit ihm von Eglon hinauf nach Hebron, und sie bekriegten es,',
        37: 'nahmen es ein und schlugen es mit der Schärfe des Schwertes samt seinem Könige und allen seinen Städten und allem Lebenden, das darin war, ohne jemand übrigzulassen, ganz wie sie Eglon getan hatten. Und sie vollstreckten den Bann an der Stadt und allem Lebenden, das darin war.',
        38: 'Darnach wandte sich Josua und ganz Israel mit ihm nach Debir, und sie bekriegten es,',
        39: 'nahmen es ein samt seinem Könige und allen seinen Städten und schlugen sie mit der Schärfe des Schwertes. Und sie vollstreckten den Bann an allem Lebenden, das darin war, ohne jemand übrigzulassen; wie sie Hebron und wie sie Libna samt seinem Könige getan hatten, so taten sie Debir und seinem Könige.',
        40: 'Also schlug Josua das ganze Land: das Gebirge, das Südland, die Niederung und die Abhänge samt allen ihren Königen, ohne jemand übrigzulassen, und an allem Lebenden vollstreckten sie den Bann, wie der Herr, der Gott Israels, geboten hatte. (a) 5Mo 20:16 17',
        41: 'Und Josua schlug sie von Kades-Barnea an bis Gaza, und das ganze Land Gosen bis Gibeon.',
        42: 'Und alle diese Könige samt ihrem Lande nahm Josua auf einmal; denn der Herr, der Gott Israels, stritt für Israel.',
        43: 'Darnach kehrte Josua und ganz Israel mit ihm nach Gilgal ins Lager zurück.',
    },
    11: {
        1: 'ALS aber Jabin, der König von Hazor, davon hörte, sandte er zu Jobab, dem König von Madon, und zum König von Simron und zum König von Achsaph',
        2: 'und zu den Königen, die im Norden, auf dem Gebirge, und in der Araba südlich von Kinneroth und in der Niederung und im Hügelland von Dor am Meere wohnten, (1) d.i. Gennesaret.',
        3: 'zu den Kanaanitern im Osten und Westen, zu den Amoritern, Hethitern, Pheresitern und Jebusitern auf dem Gebirge und zu den Hewitern am Fusse des Hermon im Lande Mizpa.',
        4: 'Und diese zogen aus mit ihrem ganzen Heer, ein Volk, so zahlreich wie der Sand am Meere, und sehr viel Rosse und Wagen.',
        5: 'Alle diese Könige taten sich zusammen und kamen und lagerten sich miteinander am Wasser von Merom, um mit Israel zu streiten.',
        6: 'Und der Herr sprach zu Josua: Fürchte dich nicht vor ihnen; denn morgen um diese Zeit gebe ich sie alle erschlagen vor Israel hin. Ihre Rosse sollst du lähmen und ihre Wagen verbrennen.',
        7: 'Da kam Josua und alles Kriegsvolk mit ihm plötzlich über sie am Wasser von Merom, und sie stürzten sich auf sie.',
        8: 'Und der Herr gab sie in die Hand Israels, und sie schlugen sie und verfolgten sie bis zu der Hauptstadt Sidon und bis Misrephoth-Maim und bis in die Talebene von Mizpa im Osten und schlugen sie, dass nicht einer von ihnen übrigblieb.',
        9: 'Da tat ihnen Josua, wie ihm der Herr geboten hatte: ihre Rosse lähmte er und ihre Wagen verbrannte er.',
        10: 'Und Josua kehrte um zu derselben Zeit und nahm Hazor ein und schlug seinen König mit dem Schwerte; Hazor war nämlich vor Zeiten die Hauptstadt aller dieser Königreiche.',
        11: 'Und sie schlugen alles Lebende, das darin war, mit der Schärfe des Schwertes, indem sie den Bann vollstreckten - nichts blieb übrig, was Atem hatte -, Hazor aber verbrannte er.',
        12: 'Auch alle Städte dieser Könige nahm Josua ein samt den Königen und schlug sie mit der Schärfe des Schwertes, indem er an ihnen den Bann vollstreckte, wie Mose, der Knecht des Herrn, geboten hatte.',
        13: 'Nur alle die Städte, die auf ihrem Hügel standen, verbrannte Israel nicht, ausgenommen Hazor; das allein verbrannte Josua.',
        14: 'Und alle Beute dieser Städte und das Vieh nahm Israel für sich; nur die Menschen alle schlugen sie mit der Schärfe des Schwertes bis zur Vernichtung; nichts Lebendes liessen sie übrig. (a) Jos 8:2; 5Mo 3:6 7',
        15: 'Wie der Herr seinem Knecht Mose geboten hatte, so hatte Mose Josua geboten, und so tat Josua; nichts unterliess er von allem, was der Herr dem Mose geboten hatte.',
        16: 'Also nahm Josua dieses ganze Land ein: das Gebirge und das ganze Südland und das ganze Land Gosen und die Niederung und die Araba und das Gebirge Israels mit seiner Niederung,',
        17: 'von dem kahlen Gebirge, welches ansteigt gegen Seir, bis nach Baal-Gad im Tal des Libanon am Fuss des Hermongebirges. Und alle ihre Könige nahm er gefangen und erschlug sie.',
        18: 'Lange Zeit führte Josua Krieg mit allen diesen Königen.',
        19: 'Da war keine Stadt, die sich friedlich mit Israel verglich, ausgenommen die Hewiter, die zu Gibeon wohnten; alles nahmen sie im Kampfe. (a) Jos 9:3-15',
        20: 'Denn vom Herrn kam die Verstockung ihres Herzens, dass sie den Krieg mit Israel wollten, - auf dass man an ihnen den Bann vollstrecke und ihnen keine Gnade widerfahre, dass sie vielmehr vertilgt würden, wie der Herr dem Mose geboten hatte.',
        21: 'Und Josua kam zu jener Zeit und rottete die Enakiter aus von dem Gebirge, von Hebron, von Debir, von Anab, von dem ganzen Gebirge Juda und von dem ganzen Gebirge Israels; an ihnen wie an ihren Städten vollstreckte Josua den Bann. (a) 4Mo 13:23',
        22: 'Es blieben keine Enakiter übrig im Lande Israels; nur in Gaza, in Gath und in Asdod blieben etliche übrig.',
        23: 'Also nahm Josua das ganze Land ein, ganz wie der Herr zu Mose geredet hatte, und gab es Israel zum Erbbesitz, einem jeden Stamme seinen Teil; und das Land hatte Ruhe vom Kriege.',
    },
    12: {
        1: 'DIES aber sind die Könige des Landes, welche die Israeliten schlugen und deren Land sie einnahmen jenseits des Jordan, gegen Sonnenaufgang, von dem Bache Arnon an bis zum Hermongebirge, und die ganze Araba gegen Osten:',
        2: 'Sihon, der König der Amoriter, der zu Hesbon wohnte und herrschte von Aroer an, das am Ufer des Baches Arnon liegt, und über die Mitte des Tales und über halb Gilead bis an den Bach Jabbok, der die Grenze der Ammoniter ist, (a) 4Mo 21:24',
        3: 'und über die Araba bis an den See Kinneroth im Osten und bis an das Meer der Araba, das Salzmeer, im Osten, in der Richtung nach Beth-Jesimoth, und im Süden am Fusse der Abhänge des Pisga; (1) d.i. Gennesaret.',
        4: 'dazu das Gebiet des Königs Og von Basan, der noch von den Rephaitern übriggeblieben war und zu Astharoth und Edrei wohnte (a) 5Mo 3:11',
        5: 'und der über das Hermongebirge und über Salcha herrschte und über ganz Basan bis an das Gebiet der Gesuriter und Maachathiter und über halb Gilead bis an das Gebiet Sihons, des Königs von Hesbon.',
        6: 'Mose, der Knecht des Herrn, und die Israeliten hatten sie geschlagen. Und Mose, der Knecht des Herrn, hatte das Land den Rubeniten, den Gaditen und dem halben Stamm Manasse zum Besitz gegeben. (a) 4Mo 32:33; 5Mo 3:12 13',
        7: 'Dies aber sind die Könige des Landes, die von Josua und den Israeliten auf der andern Seite des Jordan im Westen geschlagen wurden, von Baal-Gad im Tal des Libanon bis an das kahle Gebirge, welches ansteigt gegen Seir. Und Josua gab es den Stämmen Israels zum Besitz, einem jeden seinen Teil,',
        8: 'auf dem Gebirge, in der Niederung, in der Araba, an den Abhängen, in der Wüste und im Südland, das Land der Hethiter, Amoriter, Kanaaniter, Pheresiter, Hewiter und Jebusiter:',
        9: 'der König von Jericho, der König von Ai, das seitwärts von Bethel liegt,',
        10: 'der König von Jerusalem, der König von Hebron,',
        11: 'der König von Jarmuth, der König von Lachis,',
        12: 'der König von Eglon, der König von Geser,',
        13: 'der König von Debir, der König von Geder,',
        14: 'der König von Horma, der König von Arad,',
        15: 'der König von Libna, der König von Adullam,',
        16: 'der König von Makkeda, der König von Bethel,',
        17: 'der König von Thappuah, der König von Hepher,',
        18: 'der König von Aphek, der König von Saron,',
        19: 'der König von Madon, der König von Hazor,',
        20: 'der König von Simron-Meron, der König von Achsaph,',
        21: 'der König von Thaanach, der König von Megiddo,',
        22: 'der König von Kedes, der König von Jokneam am Karmel,',
        23: 'der König von Dor im Hügelland von Dor, der König von Gojim in Galiläa,',
        24: 'der König von Thirza - im ganzen 31 Könige.',
    },
    13: {
        1: 'ALS Josua alt und hochbetagt war, sprach der Herr zu ihm: Du bist nun alt und hochbetagt; doch bleibt noch sehr viel Land einzunehmen.',
        2: 'Dies ist das Land, das noch übriggeblieben ist: alle Kreise der Philister und ganz Gesur,',
        3: 'vom Sihor an, der östlich von Ägypten fliesst, bis zur nördlichen Grenze von Ekron - das wird zu den Kanaanitern gerechnet -, die fünf Fürsten der Philister: der von Gaza, der von Asdod, der von Askalon, der von Gath, der von Ekron, ferner die Awiter',
        4: 'im Süden, das ganze Land der Kanaaniter und Meara, das den Sidoniern gehört, bis Aphek, bis zum Gebiet der Amoriter;',
        5: 'dazu das Land der Gibliter und der ganze Libanon gegen Aufgang der Sonne, von Baal-Gad am Fusse des Hermongebirges bis nach Hamath,',
        6: 'alle, die auf dem Gebirge wohnen, vom Libanon an bis Misrephoth-Maim, alle Sidonier - ich will sie vor Israel vertreiben; nur verlose ihr Gebiet als Erbbesitz an Israel, wie ich dir geboten habe.',
        7: 'So verteile nun dieses Land als Erbbesitz unter die neun Stämme und den halben Stamm Manasse.',
        8: 'Mit ihm haben die Rubeniten und Gaditen ihren Erbbesitz empfangen, den ihnen Mose jenseits des Jordan im Osten gab - so wie ihn Mose, der Knecht des Herrn, ihnen gegeben: (1) d.h. dem andern halben Stamm Manasse. (a) 4Mo 32:33',
        9: 'von Aroer an, das am Ufer des Baches Arnon liegt, und der Stadt, die in der Mitte des Tales ist, und die ganze Ebene, von Medeba bis Dibon,',
        10: 'und alle Städte Sihons, des Königs der Amoriter, der zu Hesbon regierte, bis zum Gebiet der Ammoniter;',
        11: 'dazu Gilead und das Gebiet der Gesuriter und Maachathiter und das ganze Hermongebirge und ganz Basan bis nach Salcha,',
        12: 'das ganze Reich des Og in Basan, der zu Astharoth und Edrei regierte; der war noch übriggeblieben von dem Rest der Rephaiter. Mose aber hatte jene geschlagen und vertrieben. (a) 5Mo 3:11',
        13: 'Doch vertrieb Israel die Gesuriter und Maachathiter nicht, und so blieben Gesur und Maachath inmitten Israels wohnen bis auf diesen Tag.',
        14: 'Nur dem Stamme der Leviten gab Mose keinen Erbbesitz; der Herr, der Gott Israels, er ist ihr Erbbesitz, wie er ihnen verheissen hat. (a) 4Mo 18:20; 5Mo 10:9',
        15: 'Und Mose gab dem Stamme Ruben seinen Anteil, jedem Geschlechte für sich.',
        16: 'Und es ward ihnen das Gebiet von Aroer an, das am Ufer des Baches Arnon liegt, und der Stadt mitten im Tale; ferner die ganze Ebene bis Medeba,',
        17: 'Hesbon und alle seine Ortschaften, die in der Ebene liegen: Dibon, Bamoth-Baal und Beth-Baal-Meon,',
        18: 'Jahza, Kedemoth und Mephaat,',
        19: 'Kirjathaim, Sibma, Zereth-Hassahar auf dem Berge der Talebene,',
        20: 'Beth-Peor, die Abhänge des Pisga und Beth-Jesimoth',
        21: 'und alle Städte auf der Ebene und das ganze Reich Sihons, des Königs der Amoriter, der zu Hesbon regierte, den Mose schlug samt den Midianiterfürsten Ewi, Rekem, Zur, Hur und Reba, den Fürsten des Königs Sihon, die im Lande wohnten.',
        22: 'Auch den Wahrsager Bileam, den Sohn Beors, töteten die Israeliten mit dem Schwerte, zu den Erschlagenen hinzu. (a) 4Mo 31:8',
        23: 'Und die Grenze der Rubeniten war der Jordan und sein Gestade. Das ist der Erbbesitz der Rubeniten, auf die einzelnen Geschlechter verteilt, die Ortschaften und ihre Gehöfte.',
        24: 'Und Mose gab dem Stamme Gad seinen Anteil, jedem Geschlecht für sich,',
        25: 'und es ward ihnen folgendes Gebiet: Jaeser und alle Städte in Gilead und das halbe Land der Ammoniter bis nach Aroer, welches östlich von Rabba liegt,',
        26: 'und von Hesbon bis nach Ramath-Mizpe und Betonim, und von Mahanaim bis zum Gebiet von Debir,',
        27: 'im Tal aber Beth-Haram, Beth-Nimra, Sukkoth und Zaphon, der Rest des Reiches Sihons, des Königs von Hesbon, der Jordan und sein Gestade, bis an das Ende des Sees Kinnereth, jenseits des Jordan, ostwärts. (1) d.i. Gennesaret.',
        28: 'Das ist der Erbbesitz der Gaditen, auf die einzelnen Geschlechter verteilt, die Ortschaften und ihre Gehöfte.',
        29: 'Und Mose gab dem halben Stamm Manasse seinen Anteil, jedem Geschlecht für sich.',
        30: 'Ihr Gebiet war: ganz Basan von Mahanaim an, das ganze Reich des Königs Og von Basan, und alle Zeltdörfer Jairs, die in Basan liegen, sechzig Ortschaften, (a) Ri 10:3 4',
        31: 'und halb Gilead, Astharoth, Edrei, die Städte des Königreichs des Og in Basan; das fiel an die Nachkommen Machirs, des Sohnes Manasses, an die Hälfte der Machiriten, auf die einzelnen Geschlechter verteilt.',
        32: 'Das sind die Gebiete, die Mose ausgeteilt hat in den Gefilden Moabs, jenseits des Jordan, gegenüber Jericho im Osten.',
        33: 'Dem Stamme Levi aber hat Mose keinen Erbbesitz gegeben; denn der Herr, der Gott Israels, er ist ihr Erbbesitz, wie er ihnen verheissen hat. (a) 4Mo 18:20; 5Mo 10:9',
    },
    14: {
        1: 'DIES aber sind die Gebiete, welche die Israeliten im Lande Kanaan erhielten, die ihnen der Priester Eleasar und Josua, der Sohn Nuns, und die Stammeshäupter Israels zuteilten. (a) 4Mo 26:55; 34:17 18',
        2: 'Durchs Los teilten sie ihnen den Erbbesitz zu, wie der Herr durch Mose geboten hatte, den neuneinhalb Stämmen zu geben.',
        3: 'Denn den zweieinhalb Stämmen hatte Mose ihren Erbbesitz jenseits des Jordan gegeben. Den Leviten aber hatte er keinen Erbbesitz unter ihnen gegeben. (a) 4Mo 32:29 33',
        4: 'Denn die Nachkommen Josephs bildeten zwei Stämme, Manasse und Ephraim; und so gaben sie den Leviten keinen Gebietsteil im Lande, sondern nur Ortschaften, darin zu wohnen, und deren Weideplätze für ihr Vieh und ihre Habe. (a) 4Mo 35:2',
        5: 'Wie der Herr dem Mose geboten hatte, so taten die Israeliten und verteilten das Land.',
        6: 'Da traten die vom Stamme Juda in Gilgal vor Josua, und der Kenisiter Kaleb, der Sohn Jephunnes, sprach zu ihm: Du weisst, was der Herr zu Mose, dem Manne Gottes, meinet- und deinethalben in Kades-Barnea gesagt hat. (a) 4Mo 14:24',
        7: 'Ich war vierzig Jahre alt, als mich Mose, der Knecht des Herrn, von Kades-Barnea aussandte, das Land auszukundschaften, und ich brachte ihm Bericht, so gut, als ich es wusste.',
        8: 'Aber meine Brüder, die mit mir hinaufgezogen waren, machten dem Volk das Herz verzagt, während ich unwandelbar zum Herrn, meinem Gott, hielt.',
        9: 'Da schwur Mose an demselben Tage: Fürwahr, das Land, das dein Fuss betreten hat, soll dein und deiner Kinder Erbbesitz sein für alle Zeiten, weil du unwandelbar zum Herrn, meinem Gott, gehalten hast.',
        10: 'Und nun, siehe, hat der Herr nach seiner Verheissung mich seit der Zeit, da er zu Mose dieses sprach, diese 45 Jahre leben lassen, in deren Verlauf Israel durch die Wüste zog; so bin ich denn heute 85 Jahre alt.',
        11: 'Noch heute bin ich so stark wie an dem Tage, als mich Mose aussandte; wie damals, so habe ich auch jetzt noch die Kraft, zu streiten und aus und ein zu ziehen.',
        12: 'So gib mir nun dieses Gebirge, von dem der Herr geredet hat an jenem Tage; denn du hörtest selbst an jenem Tage, dass es dort Enakiter gibt und grosse, feste Städte. Vielleicht ist der Herr mit mir, dass ich sie vertreibe, wie der Herr geredet hat. (a) 4Mo 13:23',
        13: 'Da segnete Josua Kaleb, den Sohn Jephunnes, und gab ihm Hebron zum Erbbesitz. (a) Ri 1:20',
        14: 'Daher ward Hebron der Erbbesitz des Kenisiters Kaleb, des Sohnes Jephunnes, bis auf diesen Tag, weil er unwandelbar zum Herrn, dem Gott Israels, gehalten hatte.',
        15: 'Hebron aber hiess vor Zeiten Stadt des Arba; der war der grösste Mann unter den Enakitern. Und das Land hatte Ruhe vom Kriege. (1) [Kirjath-Arba]',
    },
    15: {
        1: 'UND das Los des Stammes Juda, auf die einzelnen Geschlechter verteilt, lag in der Richtung des Gebietes von Edom, der Wüste Zin, gegen Mittag, im äussersten Süden.',
        2: 'Und ihre Südgrenze lief vom Ende des Salzmeeres aus, von der Zunge des Meeres, die südwärts geht,',
        3: 'und sie läuft bis südlich vom Skorpionensteig, dann hinüber nach Zin und südlich von Kades-Barnea hinauf, dann an Hezron vorbei nach Addar hinauf und biegt um gegen Karka.',
        4: 'Dann geht sie hinüber nach Azmon, läuft weiter an den Bach Ägyptens und endet am Meer. Das sei eure Südgrenze.',
        5: 'Die Grenze gegen Osten aber ist das Salzmeer bis zur Mündung des Jordan, und die Grenze nach der Nordseite hin geht aus von der Zunge des Meeres, von der Mündung des Jordan;',
        6: 'dann zieht sie sich hinauf nach Beth-Hogla und läuft nördlich von Beth-Araba hin und hinauf zum Stein Bohans, des Sohnes Rubens.',
        7: 'Dann steigt die Grenze aus dem Tal Achor gegen Debir an und wendet sich nordwärts gegen Gilgal, welches dem Steig von Adummim gegenüberliegt, der südlich vom Bache ist; dann läuft sie hinüber zu dem Wasser von En-Semes und weiter bis zur Walkerquelle. (1) d.h. Sonnenquell.',
        8: 'Dann steigt die Grenze an ins Tal Ben-Hinnom, südlich von der Berglehne der Jebusiter - das ist Jerusalem -; dann steigt sie auf die Spitze des Berges, der westlich vom Tal Hinnom, am Nordende der Talebene Rephaim liegt.',
        9: 'Dann biegt die Grenze von der Spitze des Berges um zu der Quelle Me-Nephthoah und setzt sich fort bis zu den Ortschaften des Berges Ephron und biegt um nach Baala - das ist Kirjath-Jearim.',
        10: 'Von Baala wendet sich die Grenze westwärts nach dem Gebirge Seir und zieht sich weiter nach dem Nordabhang des Gebirges Jearim - das ist Chesalon -; dann senkt sie sich gegen Beth-Semes und setzt sich fort nach Thimna.',
        11: 'Dann geht die Grenze weiter an den Nordabhang von Ekron und biegt um nach Sikron; dann läuft sie weiter zum Berg Baala, setzt sich fort bis Jabneel und endet am Meer.',
        12: 'Die Grenze gegen Westen aber ist das grosse Meer und sein Gestade. Das ist die Grenze des Stammes Juda, seiner einzelnen Geschlechter, ringsum.',
        13: 'Kaleb aber, dem Sohne Jephunnes, gab er Anteil im Stammgebiete Judas nach dem Befehle des Herrn an Josua, nämlich die Stadt Arbas, des Vaters Enaks - das ist Hebron.',
        14: 'Und Kaleb vertrieb daraus die drei Söhne Enaks, Sesai, Ahiman und Thalmai, die Enakskinder, (a) 4Mo 13:23',
        15: 'und zog von da hinauf gegen die Bewohner von Debir. Debir aber hiess vor Zeiten Kirjath-Sepher.',
        16: 'Und Kaleb sprach: Wer Kirjath-Sepher schlägt und einnimmt, dem will ich meine Tochter Achsa zum Weibe geben. (a) Ri 1:12-15',
        17: 'Da nahm es Othniel ein, der Sohn des Kenas, der Bruder Kalebs; und er gab ihm seine Tochter Achsa zum Weibe. (a) Ri 3:9',
        18: 'Als sie nun einzog, stiftete er sie auf, von ihrem Vater ein Feld zu fordern. Und sie sprang vom Esel. Da sprach Kaleb zu ihr: Was hast du?',
        19: 'Sie sprach: Gib mir ein Abschiedsgeschenk; weil du mich nach dem Südland gegeben hast, so gib mir auch Wasserquellen. Da gab er ihr die obern und die untern Quellen.',
        20: 'Das ist der Erbbesitz des Stammes Juda, auf die einzelnen Geschlechter verteilt.',
        21: 'Und die Ortschaften am Rande des Stammes Juda, gegen das Gebiet von Edom hin, im Südland, waren: Kabzeel, Eder, Jagur,',
        22: 'Kina, Dimona, Adada,',
        23: 'Kedes, Hazor, Jithnan,',
        24: 'Siph, Telem, Bealoth,',
        25: 'Hazor-Hadatta, Kerioth-Hezron - das ist Hazor -,',
        26: 'Amam, Sema, Melada,',
        27: 'Hazar-Gadda, Hesmon, Beth-Pelet,',
        28: 'Hazar-Sual, Beerseba und seine Nebenorte,',
        29: 'Baala, Jjim, Ezem,',
        30: 'Eltholad, Chesil, Horma,',
        31: 'Ziklag, Madmanna, Sansanna,',
        32: 'Lebaoth, Silhim und En-Rimmon - insgesamt 29 Ortschaften mit ihren Gehöften.',
        33: 'In der Niederung: Esthaol, Zorea, Asna,',
        34: 'Sanoah, En-Gannim, Thappuah, Enam,',
        35: 'Jarmuth, Adullam, Socho, Aseka,',
        36: 'Saaraim, Adithaim, Gedera - vierzehn Ortschaften mit ihren Gehöften.',
        37: 'Zenan, Hadasa, Migdal-Gad,',
        38: 'Dilean, Mizpe, Joktheel,',
        39: 'Lachis, Bozkath, Eglon,',
        40: 'Chabbon, Lahmas, Chithlis,',
        41: 'Gederoth, Beth-Dagon, Naama, Makkeda - sechzehn Ortschaften mit ihren Gehöften.',
        42: 'Libna, Ether, Asan,',
        43: 'Jiphtah, Asna, Nezib,',
        44: 'Kegila, Achsib, Maresa - neun Ortschaften mit ihren Gehöften.',
        45: 'Ekron mit seinen Nebenorten und Gehöften,',
        46: 'von Ekron bis an das Meer alles, was seitlich von den Abhängen liegt, nebst den Gehöften,',
        47: 'Asdod mit seinen Nebenorten und Gehöften, Gaza mit seinen Nebenorten und Gehöften bis an den Bach Ägyptens, und das grosse Meer bildet die Grenze.',
        48: 'Auf dem Gebirge: Samir, Jattir, Socho,',
        49: 'Danna, Kirjath-Sanna - das ist Debir -,',
        50: 'Anab, Esthemo, Anim,',
        51: 'Gosen, Holon, Gilo - elf Ortschaften mit ihren Gehöften.',
        52: 'Arab, Duma, Esean,',
        53: 'Janum, Beth-Thappuah, Apheka,',
        54: 'Humta, Kirjath-Arba - das ist Hebron -, Zior - neun Ortschaften mit ihren Gehöften.',
        55: 'Maon, Karmel, Siph, Jutta,',
        56: 'Jisreel, Jokdeam, Sanoah,',
        57: 'Kain, Gibea, Thimna - zehn Ortschaften mit ihren Gehöften.',
        58: 'Halhul, Beth-Zur, Gedor,',
        59: 'Maarath, Beth-Anoth und Elthekon - sechs Ortschaften mit ihren Gehöften.',
        60: 'Kirjath-Baal - das ist Kirjath-Jearim - und Rabba - zwei Ortschaften mit ihren Gehöften.',
        61: 'In der Wüste: Beth-Araba, Middin, Sechacha,',
        62: 'Nibsan und die Salzstadt und Engedi - sechs Ortschaften mit ihren Gehöften.',
        63: 'Die Jebusiter aber, welche Jerusalem bewohnten, konnte Juda nicht vertreiben. Und so blieben die Jebusiter in Jerusalem neben Juda wohnen bis auf diesen Tag.',
    },
    16: {
        1: 'UND das Los fiel den Nachkommen Josephs zu: vom Jordan bei Jericho an, östlich vom Wasser Jerichos, hinauf durch die Wüste, von Jericho an auf das Gebirge nach Bethel.',
        2: 'Von Bethel geht die Grenze weiter nach Lus und dann hinüber zum Gebiet der Architer nach Ataroth',
        3: 'und steigt westwärts hinab zum Gebiet der Japhlethiter bis zum Gebiet von Unter-Beth-Horon und bis nach Geser und endet am Meer.',
        4: 'so erhielten die Söhne Josephs, Manasse und Ephraim, Erbbesitz.',
        5: 'Dies aber war das Gebiet der Ephraimiten, ihrer einzelnen Geschlechter: die Grenze ihres Erbbesitzes geht ostwärts über Ateroth-Addar nach Ober-Beth-Horon.',
        6: 'Dann läuft sie weiter bis ans Meer, Michmethath im Norden; dann wendet sie sich ostwärts nach Thaanath-Silo und geht daran vorbei östlich nach Janoah;',
        7: 'von Janoah senkt sie sich nach Ataroth und Naarath, berührt dann Jericho und endet am Jordan.',
        8: 'Von Thappuah aus läuft die Grenze westwärts an den Bach Kana und endet am Meer. Das ist der Erbbesitz des Stammes Ephraim, auf die einzelnen Geschlechter verteilt;',
        9: 'dazu die Ortschaften der Ephraimiten, welche abgesondert mitten in dem Erbbesitz der Manassiten lagen, alle Ortschaften samt ihren Gehöften.',
        10: 'Sie vertrieben aber die Kanaaniter nicht, die in Geser wohnten. Und so blieben die Kanaaniter inmitten Ephraims wohnen bis auf diesen Tag und wurden fronpflichtig.',
    },
    17: {
        1: 'Dann fiel das Los für den Stamm Manasse; denn der ist der Erstgeborne Josephs. Machir, dem Erstgebornen Manasses, dem Vater Gileads, ward Gilead und Basan zuteil, weil er ein streitbarer Mann war. (a) Jos 13:31',
        2: 'Auch unter den übrigen Nachkommen Manasses fiel jedem Geschlecht sein Los zu, den Nachkommen Abiesers, Heleks, Asriels, Sechems, Hephers und Semidas. Das sind die Nachkommen männlichen Stammes von Manasse, dem Sohne Josephs, ihre einzelnen Geschlechter.',
        3: 'Aber Zelophhad, der Sohn Hephers, des Sohnes Gileads, des Sohnes Machirs, des Sohnes Manasses, hatte keine Söhne, sondern nur Töchter; sie hiessen Mahla, Noa, Hogla, Milka und Thirza. (a) 4Mo 27:1-8',
        4: 'Diese traten vor den Priester Eleasar und vor Josua, den Sohn Nuns, und vor die Vorsteher und sprachen: Der Herr hat Mose geboten, dass er uns unter unsern Brüdern Erbbesitz gebe. Da gab er ihnen Erbbesitz unter den Brüdern ihres Vaters nach dem Befehl des Herrn.',
        5: 'So fielen auf Manasse zehn Teile ausser dem Lande Gilead und Basan jenseits des Jordan.',
        6: 'Denn die Nachkommen weiblichen Stammes von Manasse erhielten Erbbesitz unter denen männlichen Stammes. Das Land Gilead aber ward den andern Nachkommen Manasses zuteil.',
        7: 'Es lief aber die Grenze Manasses von Asser nach Michmethath, das östlich von Sichem liegt. Dann geht sie südwärts zu den Bewohnern von EnThappuah.',
        8: 'Denn das Land Thappuah ward Manasse zuteil, Thappuah aber an der Grenze Manasses den Ephraimiten.',
        9: 'Dann senkt sich die Grenze zum Bache Kana, südwärts vom Bache. Diese Ortschaften gehören zu Ephraim mitten unter den Ortschaften Manasses. Aber die Grenze von Manasse verläuft nördlich vom Bache und endet am Meer.',
        10: 'Gegen Süden gehört das Land zu Ephraim und gegen Norden zu Manasse, und das Meer ist seine Grenze; an Asser aber stossen sie im Norden und an Issaschar im Osten.',
        11: 'Es fielen aber an Manasse in Issaschar und Asser: Bethsean und seine Nebenorte, Jibleam und seine Nebenorte, die Bewohner von Dor und seinen Nebenorten, die Bewohner von En-Dor und seinen Nebenorten, die Bewohner von Thaanach und seinen Nebenorten und die Bewohner von Megiddo und seinen Nebenorten, die drei Höhenzüge.',
        12: 'Aber die Manassiten konnten diese Städte nicht einnehmen, und so gelang es den Kanaanitern, in diesem Lande wohnen zu bleiben.',
        13: 'Als aber die Israeliten erstarkt waren, machten sie die Kanaaniter fronpflichtig; doch vertreiben konnten sie dieselben nicht.',
        14: 'Da sprachen die Nachkommen Josephs zu Josua: Warum hast du uns als Erbbesitz nur ein Los und ein Teil gegeben, wo wir doch ein grosses Volk sind, da uns der Herr bisher gesegnet hat?',
        15: 'Da sprach Josua zu ihnen: Wenn ihr ein grosses Volk seid, so zieht hinauf ins Waldland und rodet daselbst im Lande der Pheresiter und Rephaiter, weil euch das Gebirge Ephraim zu enge ist.',
        16: 'Da sprachen die vom Stamme Joseph: Das Gebirge reicht nicht für uns; alle Kanaaniter aber, die in der Ebene wohnen, haben eiserne Wagen, die in Bethsean und seinen Nebenorten und die in der Ebene Jesreel.',
        17: 'Da sprach Josua zum Hause Joseph, zu Ephraim und Manasse: Du bist ein grosses Volk und hast grosse Kraft. Du sollst nicht nur ein Los haben,',
        18: 'sondern Bergland soll dir zufallen; wenn es Wald ist, so rode ihn aus, und es sollen seine Ausläufer dein sein. Denn du wirst die Kanaaniter vertreiben, obschon sie eiserne Wagen haben und stark sind.',
    },
    18: {
        1: 'UND die ganze Gemeinde der Israeliten versammelte sich zu Silo und richtete daselbst das heilige Zelt auf, nachdem das Land ihnen unterworfen war. (a) 1Sa 1:3 9',
        2: 'Es waren aber unter den Israeliten noch sieben Stämme übrig, deren Erbbesitz nicht verteilt war.',
        3: 'Und Josua sprach zu den Israeliten: Wie lange wollt ihr so lässig sein, dass ihr nicht hingeht, das Land einzunehmen, das euch der Herr, der Gott eurer Väter, gegeben hat?',
        4: 'Stellt aus jedem Stamme drei Männer, so will ich sie senden, dass sie sich aufmachen und im Lande umherziehen und es entsprechend ihrem Erbbesitz aufzeichnen und dann wieder zu mir kommen.',
        5: 'Alsdann teilt es unter euch in sieben Teile. Juda bleibt auf seinem Gebiet im Süden, und das Haus Joseph bleibt auf seinem Gebiet im Norden;',
        6: 'ihr aber macht eine Aufzeichnung des Landes in sieben Teilen und bringt sie dann zu mir hierher, so will ich euch das Los werfen hier vor dem Herrn, unserm Gotte.',
        7: 'Denn die Leviten haben keinen Anteil unter euch, sondern das Priestertum des Herrn ist ihr Erbbesitz. Gad aber und Ruben und der halbe Stamm Manasse haben jenseits des Jordan im Osten ihren Erbbesitz erhalten, den ihnen Mose, der Knecht des Herrn, gegeben hat.',
        8: 'Da machten sich die Männer auf den Weg, und Josua gebot ihnen, als sie auszogen, um das Land aufzuzeichnen: Gehet hin, ziehet im Lande umher und zeichnet es auf und kommt dann wieder zu mir, so will ich euch hier vor dem Herrn zu Silo das Los werfen.',
        9: 'Also gingen die Männer hin und durchzogen das Land und zeichneten es Stadt für Stadt in sieben Teilen in einer Schrift auf, und diese brachten sie zu Josua ins Lager nach Silo.',
        10: 'Da warf ihnen Josua das Los zu Silo vor dem Herrn, und er verteilte daselbst das Land unter die Israeliten, einem jeden sein Teil.',
        11: 'Und es kam heraus das Los des Stammes Benjamin, seiner einzelnen Geschlechter, und das Gebiet seines Loses kam zwischen Juda und Joseph zu liegen.',
        12: 'Und ihre Grenze auf der Nordseite fängt am Jordan an; dann zieht sie sich hinauf nördlich von dem Bergvorsprung bei Jericho und westwärts auf das Gebirge hinauf und endet in der Wüste von Beth-Awen;',
        13: 'von da zieht sich die Grenze nach Lus hinüber, südlich der Berglehne bei Lus - das ist Bethel -; dann senkt sie sich nach Ateroth-Addar gegen den Berg, der südlich von Unter-Beth-Horon liegt.',
        14: 'Dann biegt die Grenze um und wendet sich auf der Westseite gegen Süden von dem Berg an, der südlich von Beth-Horon liegt, und endet gegen Kirjath-Baal hin - das ist Kirjath-Jearim, eine Stadt in Juda. Das ist die Westseite.',
        15: 'Aber die Südseite beginnt am Ende von Kirjath-Jearim, und die Grenze zieht sich bis zur Quelle Me-Nephthoah;',
        16: 'dann senkt sie sich an das Ende des Berges, der herwärts vom Tale Ben-Hinnom am Nordende des Tales Rephaim liegt, senkt sich ins Tal Hinnom südlich von der Berglehne der Jebusiter und kommt hinab zur Walkerquelle.',
        17: 'Dann biegt sie um nach Norden und setzt sich fort bis En-Semes und weiter gegen Geliloth hin, das dem Steig von Adummim gegenüberliegt, und senkt sich zum Stein Bohans, des Sohnes Rubens.',
        18: 'Dann zieht sie sich hinüber nördlich der Berglehne von Beth-Araba und senkt sich in die Araba.',
        19: 'Dann geht die Grenze hinüber nördlich von der Berglehne von Beth-Hogla und endet an der Nordzunge des Salzmeeres, am Südende des Jordan.',
        20: 'Der Jordan aber begrenzt es auf der Ostseite. Das ist der Erbbesitz der Benjaminiten, ihrer einzelnen Geschlechter, nach seinen Grenzen ringsum.',
        21: 'Die Städte des Stammes Benjamin aber, seiner einzelnen Geschlechter, sind: Jericho, Beth-Hogla, Emek-Keziz,',
        22: 'Beth-Araba, Zemaraim, Bethel,',
        23: 'Awim, Para, Ophra,',
        24: 'Kephar-Ammoni, Ophni und Geba - zwölf Ortschaften mit ihren Gehöften.',
        25: 'Gibeon, Rama, Beeroth,',
        26: 'Mizpe, Kephira, Moza,',
        27: 'Rekem, Jirpeel, Tharala,',
        28: 'Zela, Eleph und Jebus - das ist Jerusalem -, Gibeath und Kirjath - vierzehn Ortschaften mit ihren Gehöften. Das ist der Erbbesitz der Benjaminiten, ihrer einzelnen Geschlechter.',
    },
    19: {
        1: 'Das zweite Los aber kam heraus für Simeon, den Stamm der Simeoniten, seine einzelnen Geschlechter, und ihr Erbbesitz lag inmitten des Erbbesitzes von Juda.',
        2: 'Ihnen fiel als Erbbesitz zu: Beerseba, Molada,',
        3: 'Hazar-Sual, Bala, Ezem,',
        4: 'Eltholad, Bethul, Horma,',
        5: 'Ziklag, Beth-Hammarkaboth, Hazar-Susa,',
        6: 'Beth-Lebaoth und Saruhen - dreizehn Ortschaften mit ihren Gehöften,',
        7: 'En-Rimmon, Thochen, Ether und Asan - vier Ortschaften mit ihren Gehöften,',
        8: 'dazu alle Gehöfte, die rings um diese Ortschaften liegen bis nach Baalath-Beer, dem Rama des Südlandes. Das ist der Erbbesitz des Stammes Simeon, seiner einzelnen Geschlechter.',
        9: 'Der Erbbesitz der Simeoniten ist von dem Anteil Judas genommen. Denn der Erbbesitz des Stammes Juda war zu gross für ihn, und so erhielten die Simeoniten Erbbesitz inmitten Judas.',
        10: 'Das dritte Los kam heraus für Sebulon, seine einzelnen Geschlechter. Und die Grenze ihres Erbbesitzes reichte bis Sarid.',
        11: 'Dann steigt ihre Grenze westwärts an gegen Marala, berührt Dabbeseth und stösst an den Bach, der herwärts von Jokneam fliesst.',
        12: 'Von Sarid ostwärts aber, gegen Sonnenaufgang, wendet sie sich nach dem Gebiet von Kisloth-Thabor, setzt sich fort nach Daberath und steigt an gegen Japhia.',
        13: 'Von da geht sie ostwärts, gegen Sonnenaufgang, nach Gath-Hepher und Eth-Kazin hinüber, setzt sich fort nach Rimmon und biegt um nach Neha.',
        14: 'Dann wendet sich die Grenze, nördlich von Hannathon, und endet im Tal Jiphthah-El.',
        15: '-...und Kattath, Nahalal, Simron, Jidala und Bethlehem - zwölf Ortschaften mit ihren Gehöften. (1) der Anfang des Satzes mit sieben Ortsnamen fehlt im überlieferten Text.',
        16: 'Das ist der Erbbesitz Sebulons, seiner einzelnen Geschlechter, diese Ortschaften und ihre Gehöfte.',
        17: 'Für die einzelnen Geschlechter der Nachkommen Issaschars kam das vierte Los heraus.',
        18: 'Und ihr Gebiet umfasste Jesreel, Kesulloth, Sunem,',
        19: 'Hapharaim, Sion, Anaharath,',
        20: 'Rabbith, Kisjon, Ebez,',
        21: 'Remeth, EnGannim, En-Hadda, Beth-Pazzez.',
        22: 'Und die Grenze berührt Thabor, Sahazima, Beth-Semes und endet am Jordan - sechzehn Ortschaften mit ihren Gehöften.',
        23: 'Das ist der Erbbesitz der einzelnen Geschlechter des Stammes Issaschar, die Ortschaften und ihre Gehöfte.',
        24: 'Das fünfte Los kam heraus für den Stamm Asser, seine einzelnen Geschlechter,',
        25: 'und ihr Gebiet umfasste: Helkath, Hali, Beten, Achsaph,',
        26: 'Alammelech, Amad, Misal, und stösst westwärts an den Karmel und an den (Fluss) Sihor-Libnath.',
        27: 'Dann wendet sich die Grenze gegen Sonnenaufgang nach Beth-Dagon, berührt Sebulon und das Tal Jiphthah-El im Norden, dann Beth-Emek und Negiel und setzt sich links fort nach Kabul,',
        28: 'Ebron, Rehob, Hammon und Kana bis zu der Hauptstadt Sidon.',
        29: 'Dann wendet sich die Grenze nach Rama und bis zu der festen Stadt Tyrus, hierauf nach Hos und endet am Meer. Mahaleb, Achsib,',
        30: 'Akko, Aphek und Rehob - 22 Ortschaften mit ihren Gehöften.',
        31: 'Das ist der Erbbesitz des Stammes Asser, seiner einzelnen Geschlechter, diese Ortschaften und ihre Gehöfte.',
        32: 'Für die einzelnen Geschlechter der Nachkommen Naphthalis kam das sechste Los heraus,',
        33: 'und ihre Grenze lief von Heleph, von der Eiche bei Zaanannim, über Adami-Nekeb und Jabneel bis nach Lakkum und endet am Jordan.',
        34: 'Dann wendet sich die Grenze westwärts nach AsnothThabor, setzt sich von da fort nach Hukkok und stösst an Sebulon im Süden; an Asser aber stösst sie im Westen und an den Jordan im Osten.',
        35: 'Und feste Städte sind: Ziddim, Zer, Hammath, Rakkath, Kinnereth,',
        36: 'Adama, Rama, Hazor,',
        37: 'Kedes, Edrei, En-Hazor,',
        38: 'Jiron, Migdal-El, Horem, Beth-Anath und Beth-Semes - neunzehn Ortschaften mit ihren Gehöften.',
        39: 'Das ist der Erbbesitz des Stammes Naphthali, seiner einzelnen Geschlechter, die Ortschaften und ihre Gehöfte.',
        40: 'Für die einzelnen Geschlechter des Stammes Dan kam das siebente Los heraus,',
        41: 'und das Gebiet ihres Erbbesitzes umfasste: Zora, Esthaol, Ir-Semes,',
        42: 'Saalabbin, Ajalon, Jithla,',
        43: 'Elon, Thimnath, Ekron,',
        44: 'Eltheke, Gibbethon, Baalath,',
        45: 'Jehud, Bene-Barak, Gath-Rimmon,',
        46: 'Me-Jarkon, Rakkon, samt dem Gebiet gegen Japho hin.',
        47: 'Aber den Daniten war ihr Gebiet zu eng; so zogen sie denn hinauf und stritten wider Lesem, eroberten und schlugen es mit der Schärfe des Schwertes, nahmen es in Besitz und liessen sich darin nieder, und sie nannten es Dan nach dem Namen ihres Vaters Dan. (a) Ri 18:27-29',
        48: 'Das ist der Erbbesitz des Stammes Dan, seiner einzelnen Geschlechter, diese Ortschaften und ihre Gehöfte.',
        49: 'Als sie nun das Land nach seinen einzelnen Gebieten ganz verteilt hatten, gaben die Israeliten Josua, dem Sohne Nuns, Erbbesitz in ihrer Mitte.',
        50: 'Nach dem Befehl des Herrn gaben sie ihm die Stadt, die er forderte, nämlich Thimnath-Serah auf dem Gebirge Ephraim; da baute er die Stadt aus und liess sich darin nieder.',
        51: 'Das sind die Erbteile, die der Priester Eleasar und Josua, der Sohn Nuns, und die Stammeshäupter Israels durch das Los verteilten in Silo vor dem Herrn, am Eingang des heiligen Zeltes. So vollendeten sie die Verteilung des Landes. (a) Jos 18:1',
    },
    20: {
        1: 'UND der Herr redete mit Josua und sprach: (a) 2Mo 21:13; 4Mo 35:11; 5Mo 19:1-13',
        2: 'Sage den Israeliten: Bestimmet euch die Freistädte, von denen ich euch durch Mose gesagt habe,',
        3: 'dass dahin fliehen möge ein Totschläger, der jemand aus Versehen, unvorsätzlich, erschlägt, damit sie euch als Zuflucht vor dem Bluträcher dienen.',
        4: 'Und wer zu einer dieser Städte flieht, der soll am Eingang des Stadttors stehenbleiben und seine Sache vor die Ältesten dieser Stadt bringen; dann sollen sie ihn zu sich in die Stadt nehmen und ihm Platz geben, dass er bei ihnen wohnen kann.',
        5: 'Und wenn der Bluträcher ihm nachjagt, sollen sie ihm den Totschläger nicht ausliefern, weil er den andern unvorsätzlich erschlagen hat, ohne dass er ihm zuvor feind war;',
        6: 'er soll aber in jener Stadt bleiben, bis er zur Entscheidung vor der Gemeinde gestanden, bis der Hohepriester stirbt, der zu jener Zeit sein wird. Alsdann soll der Totschläger wieder heim in seine Stadt und in sein Haus gehen, in die Stadt, aus der er geflohen ist.',
        7: 'Da weihten sie Kedes in Galiläa auf dem Gebirge Naphthali und Sichem auf dem Gebirge Ephraim und Kirjath-Arba - das ist Hebron - auf dem Gebirge Juda.',
        8: 'Und jenseits des Jordan, bei Jericho, im Osten, bestimmten sie Bezer in der Wüste, auf der Ebene, aus dem Stamme Ruben und Ramoth in Gilead aus dem Stamme Gad und Golan in Basan aus dem Stamme Manasse. (a) 5Mo 4:41-43',
        9: 'Das waren die Städte, die für alle Israeliten und für die Fremdlinge, welche unter ihnen wohnten, bestimmt wurden, damit jeder, der jemand aus Versehen erschlüge, dahin fliehe und nicht sterbe durch den Bluträcher, ehe er vor der Gemeinde gestanden.',
    },
    21: {
        1: 'DA traten die Familienhäupter der Leviten zu dem Priester Eleasar und zu Josua, dem Sohne Nuns, und zu den Stammeshäuptern Israels',
        2: 'und redeten mit ihnen zu Silo im Lande Kanaan und sprachen: Der Herr hat durch Mose geboten, dass man uns Ortschaften gebe zum Wohnen und deren Weideplätze für unser Vieh. (a) 4Mo 35:2-8',
        3: 'Da gaben die Israeliten den Leviten von ihrem Erbbesitz nach dem Befehl des Herrn folgende Ortschaften samt ihren Weideplätzen.',
        4: 'Und es kam das Los für die Geschlechter der Kahathiter heraus, und es fielen durch das Los unter den Leviten den Nachkommen Aarons, des Priesters, dreizehn Ortschaften zu, von dem Stamme Juda, von dem Stamme Simeon und von dem Stamme Benjamin.',
        5: 'Den übrigen Nachkommen Kahaths fielen durch das Los zehn Ortschaften zu, von den Geschlechtern des Stammes Ephraim, von dem Stamme Dan und von dem halben Stamme Manasse.',
        6: 'Den Nachkommen Gersons fielen durch das Los dreizehn Ortschaften zu, von den Geschlechtern des Stammes Issaschar, von dem Stamme Asser, von dem Stamme Naphthali und von dem halben Stamme Manasse in Basan.',
        7: 'Den Nachkommen Meraris, ihren einzelnen Geschlechtern, fielen zwölf Ortschaften zu, von dem Stamme Ruben, von dem Stamme Gad und von dem Stamme Sebulon.',
        8: 'So gaben die Israeliten den Leviten diese Ortschaften samt ihren Weideplätzen durch das Los, wie der Herr durch Mose geboten hatte.',
        9: 'Im Stamme Juda und im Stamme Simeon gaben sie folgende Ortschaften, die sie mit Namen nannten.',
        10: 'Den Nachkommen Aarons von den Geschlechtern der Kahathiter unter den Leviten - denn auf sie fiel das Los zuerst -',
        11: 'gaben sie die Stadt Arbas, des Vaters Enaks - das ist Hebron - auf dem Gebirge Juda und die Weideplätze rings um sie her.',
        12: 'Das Feld der Stadt aber und ihre Gehöfte gaben sie Kaleb, dem Sohne Jephunnes, zum Besitz. (a) Jos 14:14; 15:13',
        13: 'Den Nachkommen Aarons, des Priesters, gaben sie die Freistadt der Totschläger, Hebron und seine Weideplätze, Libna und seine Weideplätze,',
        14: 'Jattir und seine Weideplätze, Esthemoa und seine Weideplätze,',
        15: 'Holon und seine Weideplätze, Debir und seine Weideplätze,',
        16: 'Asan und seine Weideplätze, Jutta und seine Weideplätze, Beth-Semes und seine Weideplätze - neun Ortschaften in diesen zwei Stämmen;',
        17: 'im Stamme Benjamin aber: Gibeon und seine Weideplätze, Geba und seine Weideplätze,',
        18: 'Anathoth und seine Weideplätze, Almon und seine Weideplätze - vier Ortschaften.',
        19: 'Alle Ortschaften der Nachkommen Aarons, der Priester, waren dreizehn samt ihren Weideplätzen.',
        20: 'Den Geschlechtern der Nachkommen Kahaths, den übrigen Leviten unter den Nachkommen Kahaths, fielen die Ortschaften ihres Loses im Stamme Ephraim zu.',
        21: 'Und sie gaben ihnen die Freistadt der Totschläger, Sichem und seine Weideplätze auf dem Gebirge Ephraim, Geser und seine Weideplätze,',
        22: 'Kibzaim und seine Weideplätze, Beth-Horon und seine Weideplätze - vier Ortschaften;',
        23: 'im Stamme Dan: Eltheke und seine Weideplätze, Gibbethon und seine Weideplätze,',
        24: 'Ajalon und seine Weideplätze, Gath-Rimmon und seine Weideplätze - vier Ortschaften;',
        25: 'im halben Stamm Manasse: Thaanach und seine Weideplätze, Jibleam und seine Weideplätze - zwei Ortschaften.',
        26: 'Alle Ortschaften für die Geschlechter der übrigen Nachkommen Kahaths waren zehn samt ihren Weideplätzen.',
        27: 'Den Nachkommen Gersons aber unter den Geschlechtern der Leviten (gaben sie) im halben Stamm Manasse: die Freistadt der Totschläger, Golan in Basan und seine Weideplätze, Beesthera und seine Weideplätze - zwei Ortschaften;',
        28: 'im Stamme Issaschar: Kisjon und seine Weideplätze, Daberath und seine Weideplätze,',
        29: 'Jarmuth und seine Weideplätze, EnGannim und seine Weideplätze - vier Ortschaften;',
        30: 'im Stamme Asser: Misal und seine Weideplätze, Abdon und seine Weideplätze,',
        31: 'Helkath und seine Weideplätze, Rehob und seine Weideplätze - vier Ortschaften;',
        32: 'im Stamme Naphthali: die Freistadt der Totschläger, Kedes in Galiläa und seine Weideplätze, Hammoth-Dor und seine Weideplätze, Karthan und seine Weideplätze - drei Ortschaften.',
        33: 'Alle Ortschaften der Gersoniter, ihrer einzelnen Geschlechter, waren dreizehn samt ihren Weideplätzen.',
        34: 'Den Geschlechtern der Nachkommen Meraris, den übrigen Leviten, (gaben sie) im Stamme Sebulon: Jokneam und seine Weideplätze, Kartha und seine Weideplätze,',
        35: 'Dimna und seine Weideplätze, Nahalal und seine Weideplätze - vier Ortschaften;',
        36: 'im Stamme Ruben: die Freistadt der Totschläger, Bezer und seine Weideplätze, Jahza und seine Weideplätze,',
        37: 'Kedemoth und seine Weideplätze, Mephaath und seine Weideplätze - vier Ortschaften;',
        38: 'im Stamme Gad: die Freistadt der Totschläger, Ramoth in Gilead und seine Weideplätze, Mahanaim und seine Weideplätze,',
        39: 'Hesbon und seine Weideplätze, Jaeser und seine Weideplätze - zusammen vier Ortschaften;',
        40: 'alles Ortschaften für die Nachkommen Meraris, ihre einzelnen Geschlechter, die übrig waren unter den Geschlechtern der Leviten; so umfasste ihr Los zwölf Ortschaften.',
        41: 'Also waren inmitten des Besitzes der Israeliten insgesamt 48 Levitenstädte mit ihren Weideplätzen.',
        42: 'Es umfassten diese Städte je eine Ortschaft und die Weideplätze rings um sie her. So war es bei allen diesen Ortschaften.',
        43: 'So gab der Herr den Israeliten das ganze Land, wie er es ihren Vätern zugeschworen hatte, und sie nahmen es ein und liessen sich darin nieder.',
        44: 'Und der Herr verschaffte ihnen ringsum Ruhe, ganz wie er ihren Vätern geschworen hatte, und keiner hielt stand vor ihnen von all ihren Feinden; alle ihre Feinde gab der Herr in ihre Hand.',
        45: 'Nichts fiel dahin von all dem Guten, das der Herr dem Hause Israel versprochen hatte; alles traf ein. (a) Jos 23:14',
    },
    22: {
        1: 'DAMALS berief Josua die Rubeniten, die Gaditen und den halben Stamm Manasse',
        2: 'und sprach zu ihnen: Ihr habt alles gehalten, was euch Mose, der Knecht des Herrn, geboten hat, und meiner Stimme gehorcht in allem, was ich euch geboten habe. (a) 4Mo 32:20-32',
        3: 'Ihr habt eure Brüder nun während einer langen Zeit nicht verlassen; bis auf diesen Tag habt ihr das Gebot des Herrn, eures Gottes, treulich gehalten.',
        4: 'Nun aber hat der Herr, euer Gott, euren Brüdern Ruhe verschafft, wie er ihnen versprochen hat. So kehret jetzt um und ziehet hin zu euren Zelten in das Land eures Eigentums, das euch Mose, der Knecht des Herrn, jenseits des Jordan gegeben hat.',
        5: 'Nur erfüllet ja getreulich das Gebot und das Gesetz, das euch Mose, der Knecht des Herrn, verordnet hat, dass ihr den Herrn, euren Gott, liebet und ganz auf seinen Wegen wandelt und seine Gebote haltet und ihm anhanget und ihm von ganzem Herzen und von ganzer Seele dienet. (a) 5Mo 10:12',
        6: 'Und Josua segnete sie und entliess sie, und sie zogen heimwärts zu ihren Zelten.',
        7: 'Dem halben Stamm Manasse hatte Mose in Basan Besitz gegeben; der andern Hälfte gab Josua Besitz unter ihren Brüdern jenseits des Jordan im Westen. Auch segnete sie Josua, als er sie zu ihren Zelten entliess,',
        8: 'und sprach zu ihnen: Kehrt nun zurück zu euren Zelten mit reichen Schätzen und mit sehr viel Vieh, mit Silber, Gold, Erz, Eisen und Kleidern in grosser Menge; teilt mit euren Brüdern, was ihr von euren Feinden erbeutet habt.',
        9: 'Da kehrten die Rubeniten, die Gaditen und der halbe Stamm Manasse um und zogen von den Israeliten aus Silo hinweg, um ins Land Gilead zu ziehen, ins Land ihres Eigentums, wo sie sich ansässig gemacht hatten, wie der Herr durch Mose geboten hatte.',
        10: 'Und da sie nach Geliloth am Jordan kamen, das in dem Lande Kanaan liegt, bauten die Rubeniten, die Gaditen und der halbe Stamm Manasse daselbst einen Altar am Jordan, einen grossen, weithin sichtbaren Altar.',
        11: 'Und die Israeliten hörten sagen: Siehe, die Rubeniten, die Gaditen und der halbe Stamm Manasse haben den Altar gebaut gegenüber dem Lande Kanaan bei Geliloth am Jordan, jenseits des Gebietes der Israeliten.',
        12: 'Als die Israeliten das hörten, versammelte sich die ganze Gemeinde zu Silo, um wider sie ins Feld zu ziehen.',
        13: 'Und die Israeliten sandten Pinehas, den Sohn des Priesters Eleasar, zu den Rubeniten, den Gaditen und dem halben Stamm Manasse in das Land Gilead',
        14: 'und mit ihm zehn Vorsteher, je einen Vorsteher von jedem Stamme unter allen Stämmen Israels; jeder war das Haupt seines Stammes unter den Tausenden Israels.',
        15: 'Als diese nun zu den Rubeniten, den Gaditen und dem halben Stamm Manasse in das Land Gilead kamen, redeten sie mit ihnen und sprachen:',
        16: 'Also lässt euch die ganze Gemeinde des Herrn sagen: Was ist das für ein Treubruch, den ihr da an dem Gott Israels begangen habt, indem ihr euch heute von dem Herrn abkehrt, dadurch dass ihr euch einen Altar baut und euch so wider den Herrn empört? (a) 5Mo 12:13 14',
        17: 'Ist es noch nicht genug an der Missetat mit Peor, von der wir uns bis auf diesen Tag noch nicht gereinigt haben und um derentwillen die Plage über die Gemeinde des Herrn kam? (a) 4Mo 25:3',
        18: 'Und ihr wollt euch heute von dem Herrn wegwenden? Wenn ihr euch heute gegen den Herrn empört, so wird er morgen über die ganze Gemeinde Israels zürnen.',
        19: 'Doch wenn das Land, das ihr besitzt, unrein ist, so kommt herüber in das Land, das der Herr besitzt, wo die Wohnung des Herrn steht, und macht euch unter uns ansässig; nur empört euch nicht gegen den Herrn und auch nicht gegen uns, indem ihr euch noch einen Altar baut ausser dem Altar des Herrn, unsres Gottes.',
        20: 'Kam nicht, als Achan, der Sohn Serahs, am Gebannten sich vergriff, ein Zorn (Gottes) über die ganze Gemeinde Israels, wiewohl er nur ein einzelner Mann war? Starb er nicht für seine Missetat? (a) Jos 7',
        21: 'Da antworteten die Rubeniten, die Gaditen und der halbe Stamm Manasse und sprachen zu den Häuptern der Tausende Israels:',
        22: 'Der Gott der Götter, Jahwe, der Gott der Götter, Jahwe, er weiss, und Israel soll es auch wissen: Ist es aus Empörung oder Untreue gegen ihn, den Herrn, geschehen, (1) vgl. Anm. zu 1Mo 4:26.',
        23: 'dass wir uns einen Altar gebaut haben, um uns von dem Herrn abzuwenden, so helfe er uns heute nicht! Und geschah es, um Brandopfer und Speisopfer darauf zu opfern oder Heilsopfer darauf darzubringen, so ahnde es der Herr!',
        24: 'Vielmehr haben wir es deshalb getan, weil wir besorgten, es möchten künftig eure Kinder zu unsern Kindern sagen: "Was geht euch der Herr, der Gott Israels, an?',
        25: 'Hat doch der Herr den Jordan zur Grenze gesetzt zwischen uns und euch, ihr Rubeniten und Gaditen; ihr habt keinen Teil an dem Herrn." Damit werden eure Kinder unsre Kinder von der Furcht des Herrn abwendig machen.',
        26: 'Darum dachten wir: Wir wollen uns doch den Altar bauen, nicht für Brandopfer noch für Schlachtopfer,',
        27: 'sondern Zeuge soll er sein zwischen uns und euch und unsern Nachkommen, dass wir den Dienst des Herrn üben wollen vor ihm mit unsern Brandopfern, Schlachtopfern und Heilsopfern und dass eure Kinder künftig nicht zu unsern Kindern sagen: "Ihr habt keinen Teil an dem Herrn." (a) Jos 24:27',
        28: 'Und wir dachten: Wenn sie aber künftig so zu uns und unsern Nachkommen sprechen sollten, so können wir sagen: Sehet das Abbild des Altars des Herrn, das unsre Väter gemacht haben, nicht für Brandopfer noch für Schlachtopfer, sondern dass er zwischen uns und euch Zeuge sei.',
        29: 'Das sei ferne von uns, dass wir uns gegen den Herrn empören und uns heute von dem Herrn abwenden, indem wir einen Altar bauen für Brandopfer, für Speisopfer und für Schlachtopfer, ausser dem Altar des Herrn, unsres Gottes, der vor seiner Wohnung steht.',
        30: 'Als aber der Priester Pinehas und die Vorsteher der Gemeinde, die Häupter der Tausende Israels, die bei ihm waren, die Worte hörten, welche die Rubeniten, Gaditen und Manassiten sprachen, gefielen sie ihnen wohl.',
        31: 'Und Pinehas, der Sohn des Priesters Eleasar, sprach zu den Rubeniten, Gaditen und Manassiten: Heute erkennen wir, dass der Herr unter uns ist, weil ihr da nicht einen Treubruch an dem Herrn begangen habt. Nun habt ihr die Israeliten aus der Hand des Herrn errettet.',
        32: 'Darnach kehrten Pinehas, der Sohn des Priesters Eleasar, und die Vorsteher von den Rubeniten und Gaditen aus dem Lande Gilead zurück in das Land Kanaan zu den Israeliten und brachten ihnen Bericht.',
        33: 'Da gefiel die Sache den Israeliten wohl, und sie lobten Gott und dachten nicht mehr daran, wider die Rubeniten und Gaditen ins Feld zu ziehen, um das Land zu verheeren, in dem diese wohnten.',
        34: 'Und die Rubeniten und Gaditen nannten den Altar Ed; denn, (sagten sie,) Zeuge soll er sein zwischen uns, dass Jahwe der (wahre) Gott ist. (1) d.h. Zeuge. (2) vgl. Anm. zu 1Mo 4:26.',
    },
    23: {
        1: 'UND nach langer Zeit, als der Herr den Israeliten vor all ihren Feinden ringsum Ruhe verschafft hatte und Josua alt und hochbetagt war,',
        2: 'berief Josua ganz Israel, seine Ältesten, Häupter, Richter und Amtleute, und sprach zu ihnen: Ich bin nun alt und hochbetagt,',
        3: 'ihr aber habt alles gesehen, was der Herr, euer Gott, getan hat an all diesen Völkern vor euch; denn der Herr, euer Gott, hat selbst für euch gestritten.',
        4: 'Sehet, ich habe euch diese übrigen Völker durch das Los zugeteilt, einem jeden Stamme seinen Erbbesitz, aus all den Völkern, die ich ausgerottet habe vom Jordan an bis an das grosse Meer gegen Sonnenuntergang.',
        5: 'Und der Herr, euer Gott, selbst wird sie vor euch ausstossen und vor euch vertreiben, und ihr werdet ihr Land einnehmen, wie euch der Herr, euer Gott, verheissen hat. (a) 4Mo 33:53',
        6: 'So seid nun recht fest, alles zu halten und zu tun, was im Buche des Gesetzes Moses geschrieben steht, indem ihr nicht davon abweicht, weder zur Rechten noch zur Linken, (a) 5Mo 5:32',
        7: 'damit ihr euch nicht mit diesen Völkern vermenget, die noch bei euch übrig sind, und nicht den Namen ihrer Götter erwähnet, bei ihnen schwöret, ihnen dienet und sie anbetet, (a) 2Mo 23:13',
        8: 'sondern dem Herrn, eurem Gott, sollt ihr anhangen, wie ihr bis auf diesen Tag getan habt.',
        9: 'Darum hat der Herr grosse und mächtige Völker vor euch vertrieben, und euch hat niemand standgehalten bis auf diesen Tag.',
        10: 'Ein einziger von euch jagt tausend vor sich her; denn der Herr, euer Gott, streitet selbst für euch, wie er euch verheissen hat. (a) 3Mo 26:8',
        11: 'Darum seid um eures Lebens willen darauf bedacht, dass ihr den Herrn, euren Gott, liebhabet;',
        12: 'denn wenn ihr euch abwendet und dem Rest dieser Völker anhanget, die da noch bei euch übriggeblieben sind, und euch mit ihnen verschwägert, dass ihr euch miteinander vermenget, (a) 5Mo 7:3',
        13: 'so wisset wohl, dass der Herr, euer Gott, diese Völker nicht mehr vor euch vertreiben wird, sondern sie werden euch zur Schlinge und zum Fallstrick werden, zur Geissel an euren Seiten und zu Dornen in euren Augen, bis ihr vertilgt seid aus diesem schönen Lande, das euch der Herr, euer Gott, gegeben hat. (a) 2Mo 23:33; 4Mo 33:55',
        14: 'Siehe, ich gehe heute den Weg aller Welt. So bedenket denn von ganzem Herzen und von ganzer Seele, dass nichts hinfällig geworden ist von all dem Guten, das der Herr, euer Gott, euch verheissen hat. Alles ist eingetroffen; nichts ist ausgeblieben. (a) 1Kön 2:2; Jos 21:45',
        15: 'Wie nun alles Gute eingetroffen ist, das der Herr, euer Gott, euch verheissen hat, so wird der Herr auch alles Böse über euch kommen lassen, bis er euch vertilgt hat aus diesem schönen Lande, das euch der Herr, euer Gott, gegeben hat, (a) 5Mo 28:15-68',
        16: 'wenn ihr die Bundesordnung, die der Herr, euer Gott, euch gegeben hat, übertretet und hingeht und andern Göttern dient und sie anbetet; und der Zorn des Herrn wird über euch entbrennen, und ihr werdet bald vertilgt sein aus dem schönen Lande, das er euch gegeben hat.',
    },
    24: {
        1: 'UND Josua versammelte alle Stämme Israels zu Sichem und berief die Ältesten Israels, seine Häupter, Richter und Amtleute. Und als sie vor Gott getreten waren,',
        2: 'sprach Josua zu dem ganzen Volke: So spricht der Herr, der Gott Israels: Eure Väter, Tharah, Abrahams und Nahors Vater, wohnten vor Zeiten jenseits des (Euphrat-)Stromes und dienten andern Göttern. (a) 1Mo 11:31; 35:2',
        3: 'Da holte ich euren Vater Abraham von der andern Seite des Stromes und liess ihn durch das ganze Land Kanaan wandern und mehrte sein Geschlecht und gab ihm Isaak. (a) 1Mo 21:2',
        4: 'Dem Isaak aber gab ich Jakob und Esau; und dem Esau gab ich das Gebirge Seir zum Besitz. Jakob aber und seine Söhne zogen hinab nach Ägypten. (a) 1Mo 25:24-26; 36:8; 46:6',
        5: 'Dann sandte ich Mose und Aaron und schlug Ägypten mit dem, was ich in seiner Mitte tat. Darnach führte ich euch heraus. (a) 2Mo 3',
        6: 'Und ich führte eure Väter aus Ägypten. Und als ihr ans Meer kamt und die Ägypter euren Vätern mit Wagen und Reitern an das Schilfmeer nachjagten, (a) 2Mo 14',
        7: 'da schrieen sie zum Herrn; der setzte Finsternis zwischen euch und die Ägypter und liess das Meer über sie kommen, und es bedeckte sie. Und eure Augen sahen, was ich den Ägyptern getan habe. Darnach habt ihr lange Zeit in der Wüste geweilt.',
        8: 'Dann brachte ich euch in das Land der Amoriter, die jenseits des Jordan wohnten; und als sie wider euch stritten, gab ich sie in eure Hand, und ihr nahmt ihr Land in Besitz, und ich vertilgte sie vor euch. (a) 4Mo 21:25',
        9: 'Da erhob sich Balak, der Sohn Zippors, der König von Moab, und stritt wider Israel; und er sandte hin und liess Bileam, den Sohn Beors, rufen, dass er euch verfluche. (a) 4Mo 22:4-6',
        10: 'Aber ich wollte nicht auf Bileam hören, sondern er musste euch immer wieder segnen, und ich errettete euch aus seiner Hand.',
        11: 'Und als ihr über den Jordan ginget und nach Jericho kamet, stritten wider euch die Bürger von Jericho, die Amoriter, Pheresiter, Kanaaniter, Hethiter, Girgasiter, Hewiter und Jebusiter; aber ich gab sie in eure Hand. (a) Jos 3:16; 6:1-20',
        12: 'Und ich sandte die Hornissen vor euch her; die vertrieben sie vor euch, die zwölf Könige der Amoriter - nicht durch dein Schwert und nicht durch deinen Bogen. (a) 2Mo 23:28; 5Mo 7:20',
        13: 'Und ich gab euch ein Land, um das ihr euch nicht abgemüht, und Städte, die ihr nicht gebaut und doch zum Wohnsitz bekommen habt; ihr esset von Weinbergen und Ölbäumen, die ihr nicht gepflanzt habt. (a) 5Mo 6:10 11',
        14: 'So fürchtet nun den Herrn und dienet ihm aufrichtig und treu; tut die Götter von euch, denen eure Väter jenseits des (Euphrat-)Stromes und in Ägypten gedient haben, und dienet dem Herrn.',
        15: 'Gefällt es euch aber nicht, dem Herrn zu dienen, so wählet heute, wem ihr dienen wollt: den Göttern, denen eure Väter jenseits des Stromes gedient haben, oder den Göttern der Amoriter, in deren Land ihr wohnt. Ich aber und mein Haus, wir wollen dem Herrn dienen.',
        16: 'Da antwortete das Volk und sprach: Das sei ferne von uns, dass wir den Herrn verlassen und andern Göttern dienen!',
        17: 'Denn der Herr ist unser Gott; er ist es, der uns und unsre Väter aus dem Lande Ägypten, aus dem Sklavenhause, geführt und vor unsern Augen diese grossen Zeichen getan und uns behütet hat auf dem ganzen Wege, den wir gegangen, und unter allen Völkern, durch die wir mitten hindurchgezogen sind. (a) 2Mo 20:2',
        18: 'Und der Herr hat alle Völker, auch die Amoriter, die im Lande wohnten, vor uns vertrieben. Auch wir wollen dem Herrn dienen, denn er ist unser Gott.',
        19: 'Da sprach Josua zum Volke: Ihr könnt dem Herrn nicht dienen, denn er ist ein heiliger Gott; ein eifersüchtiger Gott ist er: er wird euch eure Übertretung und eure Sünden nicht vergeben. (a) 2Mo 20:5; 3Mo 19:2',
        20: 'Wenn ihr den Herrn verlasst und fremden Göttern dient, so wird er sich wenden und euch Übles tun und euch aufreiben, nachdem er euch Gutes getan hat.',
        21: 'Da sprach das Volk zu Josua: Nein! dem Herrn wollen wir dienen.',
        22: 'Josua aber sprach zum Volke: Ihr seid Zeugen gegen euch selbst, dass ihr euch den Herrn erwählt habt, ihm zu dienen - und sie sprachen: Wir sind Zeugen -;',
        23: 'so tut nun von euch die fremden Götter, die unter euch sind, und neiget euer Herz dem Herrn zu, dem Gott Israels. (a) 1Mo 35:2',
        24: 'Und das Volk sprach zu Josua: Dem Herrn, unserm Gott, wollen wir dienen und auf seine Stimme hören.',
        25: 'Also verpflichtete Josua das Volk an jenem Tage und gab ihm Gesetz und Recht in Sichem.',
        26: 'Und Josua schrieb dies alles in das Buch des Gesetzes Gottes, und er nahm einen grossen Stein und richtete ihn daselbst auf unter der Eiche, die beim Heiligtum des Herrn steht. (a) 1Mo 35:4; Ri 9:6',
        27: 'Und Josua sprach zum ganzen Volke: Siehe, dieser Stein soll Zeuge gegen uns sein; denn er hat alle Worte gehört, die der Herr mit uns geredet hat, und er soll Zeuge gegen euch sein, damit ihr euren Gott nicht verleugnet. (a) 1Mo 31:48',
        28: 'Dann entliess Josua das Volk, einen jeden in sein Eigentum.',
        29: 'Und es begab sich nach alledem, dass Josua, der Sohn Nuns, der Knecht des Herrn, starb, als er 110 Jahre alt war.',
        30: 'Und man begrub ihn im Gebiete seines Erbbesitzes zu Thimnath-Serah, das auf dem Gebirge Ephraim liegt, nördlich vom Berge Gaas. (a) Jos 19:50',
        31: 'Und Israel diente dem Herrn, solange Josua lebte und die Ältesten, die Josua überlebten und die alles kannten, was der Herr für Israel getan hatte. (a) Ri 2:7',
        32: 'Und die Gebeine Josephs, welche die Israeliten aus Ägypten heraufgebracht hatten, begruben sie zu Sichem in dem Grundstück, das Jakob von den Söhnen Hemors, des Vaters Sichems, um hundert Kesita gekauft und Joseph zum Erbbesitz gegeben hatte. (a) 1Mo 33:19; 50:25; 2Mo 13:19',
        33: 'Und als Eleasar, der Sohn Aarons, gestorben war, begrub man ihn zu Gibea, der Stadt seines Sohnes Pinehas, die ihm auf dem Gebirge Ephraim gegeben worden war.',
    },
}
